// iteration-G14/G15: read-only view of the Win32 activity counters
// incremented by win32/user32_window.cpp (message queue), win32/
// winmm_ign.cpp (timers/joystick), win32/kernel32_ign.cpp (file I/O + a
// total-calls aggregate), and win32/dinput.cpp (DirectInput vtable calls)
// -- same plain-C-global cross-TU pattern those files already use for
// g_ign_msg_queue_depth. Used ONLY by the frame-loop diagnostic summary
// below to answer "what is the guest doing between presents" -- never
// written from this file.
extern "C" {
    extern volatile uint32_t g_ign_peekmessage_count;
    extern volatile uint32_t g_ign_getmessage_count;
    extern volatile uint32_t g_ign_dispatchmessage_count;
    extern volatile uint32_t g_ign_postmessage_count;
    extern volatile uint32_t g_ign_user32_call_count;
    extern volatile uint32_t g_ign_timegettime_count;
    extern volatile uint32_t g_ign_timesetevent_count;
    extern volatile uint32_t g_ign_timekillevent_count;
    extern volatile uint32_t g_ign_joygetposex_count;
    extern volatile uint32_t g_ign_winmm_call_count;
    extern volatile uint32_t g_g99TimeGetTimeSerial;
    extern volatile uint32_t g_g99TimeGetTimeValue;
    extern volatile uint32_t g_g99TimeGetTimeCaller;
    extern volatile uint32_t g_g99QpcSerial;
    extern volatile uint64_t g_g99QpcValue;
    extern volatile uint32_t g_g99QpcCaller;
    extern volatile uint32_t g_ign_kernel32_call_count;
    extern volatile uint32_t g_ign_createfilea_count;
    extern volatile uint32_t g_ign_readfile_count;
    extern volatile uint32_t g_ign_dinput_call_count;
    extern volatile uint32_t g_g98AcceptSerial;
}

