// iteration-G4: vitaGL is only ever CALLED from the 3dfx-only code path
// (grSstWinOpen_impl below, guarded), but this whole translation unit is
// compiled for BOTH renderer branches (CMakeLists.txt's shared source
// list -- see the header comment there), so this #include and every
// vitaGL/SceGxm symbol reference must stay inside IGNITION_RENDERER_3DFX
// guards too, or the stable DDraw build would need to link vitaGL for
// code it never runs. The DDraw build's CMakeLists target does NOT link
// libvitaGL.a at all -- keep it that way.
#ifdef IGNITION_RENDERER_3DFX
#include <vitaGL.h>
#include <psp2/kernel/threadmgr.h>
#include <psp2/kernel/sysmem.h>
#include <psp2/kernel/processmgr.h>
// iteration-G81, Parte 8/9: real Vita SDK display API (sceDisplayGetFrameBuf),
// read-only -- never calls sceDisplaySetFrameBuf, never changes display mode.
#include <psp2/display.h>
// iteration-G138: READ-ONLY clock query for the telemetry's start line (the CPU/GPU clocks must be reported with every baseline). Nothing is ever set.
#include <psp2/power.h>
// iteration-G159: the system keyboard (SceImeDialog) for the player name; the common dialog is presented by vitaGL's swap (vglSwapBuffers(GL_TRUE)); AppUtil + the common dialog configuration are set up once, the first time the keyboard is opened.
#include <psp2/apputil.h>          // G159
#include <psp2/system_param.h>     // G159
#include <psp2/common_dialog.h>    // G159
#include <psp2/ime_dialog.h>       // G159
#include <psp2/sysmodule.h>        // G159
#endif

