void g102_init_texture(){if(g_glideContext.lfb_texture_initialized)return;GLuint tex=0;glGenTextures(1,&tex);glBindTexture(GL_TEXTURE_2D,tex);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);glTexImage2D(GL_TEXTURE_2D,0,GL_RGB,g_glideContext.width,g_glideContext.height,0,GL_RGB,GL_UNSIGNED_SHORT_5_6_5,nullptr);g_glideContext.lfb_texture=tex;g_glideContext.lfb_texture_initialized=true;}
