// the sampled stamps of one guDrawTriangleWithClip call (every 32nd call, its own phase: the G148 sampler is on phase 0): 8 stamps delimit the 7 segments of ign::g149::Seg. RAII: every return path reports.
struct G149TriProbe {
    uint64_t t[ign::g149::kTriMarks]; uint32_t marks = 0; bool on = false;
    G149TriProbe() { G149Rt& g = g_g149; if (g.on(ign::g149::kGrSeg) && (++g.triCalls & 31u) == 16u && g.gate) { on = true; t[0] = wx86_now_us(); marks = 1; } }
    inline void mark(uint32_t i) { if (__builtin_expect(on, 0) && i == marks && marks < ign::g149::kTriMarks) t[marks++] = wx86_now_us(); }
    ~G149TriProbe() {
        if (__builtin_expect(!on, 1)) return;
        if (marks == 2) t[marks++] = wx86_now_us();   // the call ended in level 0 (rejected): its end is here
        g_g149.seg.add(t, marks); g_g149.raceSeg.add(t, marks);
    }
};
// what a wrapped call needs applied of the pending GL state (g148_packet.h kNeed*): texture-only calls, matrices / viewport, arrays and read-backs can observe neither blend nor scissor; everything else (draws, a CLEAR -- it is drawn by the driver\n// with the current scissor and its own program, kept conservative --, queries, the swap, glUseProgram ...) needs both. A wrapper that knows better passes its own mask (glIsEnabled by capability, glScissor, glBlendFuncSeparate, the depth / cull / colour setters).
inline uint32_t g148_need_of_kind(uint8_t kind) {
    switch (kind) {
        case ign::g144::kGkBind: case ign::g144::kGkTexEnv: case ign::g144::kGkTexData: case ign::g144::kGkMatrix: case ign::g144::kGkArray: case ign::g144::kGkRead: return 0u;
        default: return ign::g148::kNeedAll;
    }
}

// closes the open session (flush in order + restore the baseline) and drains pending GL errors: the prelude of every wrapped call (the logic is ign::g139::pre, proven by tools/g139_test.cpp)
// iteration-G144 (G145 preparation): `kind` = the wrapper that is about to run; when it finds a draw session open it is the CAUSE of a "boundary" close and is counted (kind, Glide call in progress)
#if IGN_DIAG_FULL
inline void g139_pre_core(uint8_t kind) { G139Rt& g = g_g139; if (g.session.open()) g145_note_close(kind); ign::g139::pre(g.session, g.gl, g.pre); }
#else
inline void g139_pre_core(uint8_t) { G139Rt& g = g_g139; ign::g139::pre(g.session, g.gl, g.pre); }   // iteration-G145 (LIGHT): the cause table is a FULL-build diagnostic; the argument stays so every wrapper below is unchanged
#endif
// iteration-G148: the prelude of every wrapped call = the G146 prelude, preceded by the application of the pending GL state when something is pending (one predictable flag test otherwise)
inline void g139_pre(uint8_t kind = ign::g144::kGkOther, uint32_t need = 0xFFFFu) {
    if (__builtin_expect(g_g148.p.pending(), 0)) { const uint32_t n = need == 0xFFFFu ? g148_need_of_kind(kind) : need; if (g_g148.p.pending_mask() & n) g148_apply(kind == ign::g144::kGkSwap ? ign::g148::kSyncSwap : ign::g148::kSyncForeign, n); }
    g139_pre_core(kind);
}
// writes of blend / scissor state by anyone but the apply itself (the immediate path, the compositor, the HUD, the G125 replay ...): the new value is what both sides hold, as if G146 had written it
inline void g148_note_toggle(GLenum cap, bool on) {
    if (cap != GL_BLEND && cap != GL_SCISSOR_TEST) return;
    G148Rt& s = g_g148; s.p.foreign_toggle((uint32_t)cap, on);
#if IGN_DIAG_FULL
    if (cap == GL_BLEND) { s.ref.blendKnown = true; s.ref.blendOn = on; } else { s.ref.scKnown = true; s.ref.scOn = on; }
#endif
}
inline void g148_note_factors(GLenum a, GLenum b, GLenum c, GLenum d) {
    G148Rt& s = g_g148; const uint32_t f[4] = {(uint32_t)a, (uint32_t)b, (uint32_t)c, (uint32_t)d}; s.p.foreign_factors(f);
#if IGN_DIAG_FULL
    s.ref.fKnown = true; memcpy(s.ref.f, f, sizeof f);
#endif
}
inline void g148_note_rect(GLint x, GLint y, GLsizei w, GLsizei h) {
    G148Rt& s = g_g148; const ign::g148::Rect r{(int32_t)x, (int32_t)y, (int32_t)w, (int32_t)h}; s.p.foreign_rect(r);
#if IGN_DIAG_FULL
    s.ref.rectKnown = true; s.ref.rect = r;
#endif
}
// a new GL / Glide context: what is pending reaches GL first (G146 had issued it), then nothing is known any more
inline void g148_context_reset() {
    G148Rt& s = g_g148; if (s.p.pending()) g148_apply(ign::g148::kSyncForeign);
    s.p.gl_reset(); s.p.resync();
#if IGN_DIAG_FULL
    s.ref = ign::g148::GlState{};
#endif
}
