#if IGN_DIAG_FULL
// iteration-G148 (FULL builds only): the reference. `ref` is the immediate G146 machine (every write applied the moment it happens); after an apply, `applied` (= `desired`) must equal it for everything GL can show: blend on/off,
// the factors while blending, scissor on/off, the rectangle while it is on. The first difference switches OFF ONLY the family that diverged (blend or clip), logs the call and the field, and makes GL hold exactly what G146 would.
void g148_check_ref(const char* where) {
    G148Rt& s = g_g148; ++s.verified; ++s.winVerified;
    const uint32_t m = ign::g148::diff_effective(s.ref, s.p.applied);
    if (!m) return;
    ++s.mismatches; ++s.winMismatches;
    uint32_t off = 0; if (m & (ign::g148::kFBlendOn | ign::g148::kFFactors)) off |= ign::g148::kGrBlend; if (m & (ign::g148::kFScissorOn | ign::g148::kFRect)) off |= ign::g148::kGrClip;
    s.groups &= ~off;
    char fields[96]; ign::g148::field_names(m, fields, sizeof fields);
    snprintf(s.offWhy, sizeof s.offWhy, "%s: %s", where, fields);
    IGN_LOG("[G148-FAMILY-DISABLED]", "FULL verifier: at %s the applied GL state differs from the immediate (G146) reference in: %s | reference blend=%d/%d factors=%x,%x,%x,%x scissor=%d/%d rect=(%d,%d,%d,%d) | applied blend=%d/%d factors=%x,%x,%x,%x scissor=%d/%d rect=(%d,%d,%d,%d) | "
            "family switched OFF for the rest of the run (groups now 0x%02x); GL is brought to the reference state and the immediate G146 path takes over for it",
            where, fields, s.ref.blendKnown ? 1 : 0, s.ref.blendOn ? 1 : 0, s.ref.f[0], s.ref.f[1], s.ref.f[2], s.ref.f[3], s.ref.scKnown ? 1 : 0, s.ref.scOn ? 1 : 0, s.ref.rect.x, s.ref.rect.y, s.ref.rect.w, s.ref.rect.h,
            s.p.applied.blendKnown ? 1 : 0, s.p.applied.blendOn ? 1 : 0, s.p.applied.f[0], s.p.applied.f[1], s.p.applied.f[2], s.p.applied.f[3], s.p.applied.scKnown ? 1 : 0, s.p.applied.scOn ? 1 : 0,
            s.p.applied.rect.x, s.p.applied.rect.y, s.p.applied.rect.w, s.p.applied.rect.h, s.groups);
    s.p.force_desired(s.ref);
    g148_apply(ign::g148::kSyncForeign);
}
#endif

// iteration-G148: apply the NET difference between desired and applied INSIDE the open draw session: the pending triangles are drawn first (in order, at the state they were submitted under), then the GL calls of the plan are issued
// with the raw ops (the session is NOT closed and re-opened: that was ~25 GL calls per change in G146 and G147); the shadow follows. The order of the calls is G146's: enable / disable, factors, scissor enable / disable, rectangle.
void g148_apply(ign::g148::SyncWhy why, uint32_t need) {
    G148Rt& s = g_g148; G139Rt& g = g_g139;
    const bool open = g.session.open();
    const ign::g148::Plan p = s.p.take_plan(why, open && g.session.pending() > 0, need);
    if (!p.empty()) {
        const ign::g148::GlState d = s.p.desired;
        if (open) g.session.flush_pending(g.gl);
        if (p.blend == ign::g148::kEnable) { g.gl.enable(GL_BLEND); g.shadow.track_toggle((uint32_t)GL_BLEND, true); } else if (p.blend == ign::g148::kDisable) { g.gl.disable(GL_BLEND); g.shadow.track_toggle((uint32_t)GL_BLEND, false); }
        if (p.blendFunc) g.gl.blend_func(d.f);
        if (p.scissor == ign::g148::kEnable) { g.gl.enable(GL_SCISSOR_TEST); g.shadow.track_toggle((uint32_t)GL_SCISSOR_TEST, true); } else if (p.scissor == ign::g148::kDisable) { g.gl.disable(GL_SCISSOR_TEST); g.shadow.track_toggle((uint32_t)GL_SCISSOR_TEST, false); }
        if (p.rect) g.gl.scissor_rect(d.rect.x, d.rect.y, d.rect.w, d.rect.h);
        g.pre.errPending = true;   // a GL error of these calls is drained by the next prelude, as for the draws
        s.p.finish_apply(p);
    }
#if IGN_DIAG_FULL
    if (s.autoOn && !s.p.pending()) g148_check_ref(why == ign::g148::kSyncVisible ? "visible triangle" : why == ign::g148::kSyncSwap ? "swap" : "foreign GL call");   // (a partial apply leaves the other part pending: nothing to compare yet)
#endif
}
#endif   // IGNITION_RENDERER_3DFX (G139 wrappers)

// The exact 34 decorated import names, byte-verified against Ign_3dfx.exe's
// real import table (audit/glide_calls.csv, this project's own prior
// session). argBytes is the real @N stdcall byte count from that same
// decoration -- NOT guessed, so Shim::argc (and the stdcall cleanup that
// happens on return) is correct, and so the args this trap logs are the
// real dwords the game actually pushed, not a fabricated subset.
// grGlideInit and grSstQueryHardware are handled separately below (real
// implementations, not traps).
struct GlideFn { const char* decoratedName; uint32_t argBytes; };

static const GlideFn kGlideFns[] = {
    // iteration-G90: grChromakeyValue moved OUT of this generic/
    // unimplemented list -- it now has a real implementation
    // (grChromakeyValue_impl) and its own registered shim, same pattern
    // as grChromakeyMode before it.
    {"_grGlideGetState@4",         4},
    {"_grGlideSetState@4",         4},
    {"_grGlideShutdown@0",         0},
    {"_grSstWinClose@0",           0},
};

// iteration-G1/G2/G3: minimal logical Glide host state -- NOT a Voodoo,
// not vitaGL, not a framebuffer.
struct GlideState {
    bool initialized = false;
    bool hwQueried = false;
    bool sstSelected = false;
    int  selectedSst = -1;
    // G2's own written config -- num_sst=1, so which_sst must be 0. Kept
    // as a named constant here (not re-derived) so grSstSelect's range
    // check is provably checking against the SAME value G2 wrote, not a
    // second, possibly-drifting copy.
    static constexpr int kNumSst = 1;
};
GlideState g_glideState;

// iteration-G4: state for the first real graphics context. Field list is
// exactly the one specified this iteration -- no extra bookkeeping added
// ("no sobrediseñar"). Glide types (FxU32/GrScreenResolution_t/...) come
// from glide2x_ign.h's own understanding of Glide 2.x's public headers
// (semantics only, per audit/NFS2_GLIDE_REFERENCE.md's licensing notes --
// no code copied); represented here with plain C++ integer types since
// this project doesn't vendor Glide's own headers.
struct GlideContext {
    bool     initialized = false;
    bool     window_open = false;
    int      selected_sst = -1;
    bool     vitagl_initialized = false;
    uint32_t hwnd = 0;
    uint32_t resolution = 0;      // GrScreenResolution_t
    uint32_t refresh = 0;         // GrScreenRefresh_t
    uint32_t color_format = 0;    // GrColorFormat_t
    uint32_t origin = 0;          // GrOriginLocation_t
    int      width = 0;           // logical (Glide) width, e.g. 640
    int      height = 0;          // logical (Glide) height, e.g. 400
    // iteration-G4E: physical is the Vita's fixed panel size -- vitaGL is
    // initialized at this size once grSstWinOpen actually runs (see
    // grSstWinOpen_impl). Not queried, since it's a constant of the
    // hardware.
    int      physical_width = 960;
    int      physical_height = 544;
    int      num_color_buffers = 0;
    int      num_aux_buffers = 0;
    // iteration-G5: GrBuffer_t selected by grRenderBuffer -- logical state
    // only, no real framebuffer/target switch performed yet (Part E: that
    // architecture decision is deferred until grBufferClear/grBufferSwap/
    // LFB/draw calls show how Ignition actually uses it).
    uint32_t render_buffer = 0;   // GrBuffer_t
    // iteration-G6: GrDepthBufferMode_t selected by grDepthBufferMode --
    // logical state only, no GL_DEPTH_TEST enable/disable performed yet
    // (Part D/Q: waiting to see the full depth/cull state-setup sequence
    // -- grDepthBufferFunction/grDepthMask/grCullMode -- before mapping
    // any of it to vitaGL).
    uint32_t depth_buffer_mode = 0;   // GrDepthBufferMode_t
    // iteration-G7: FxBool written by grDepthMask -- logical state only,
    // no glDepthMask() call performed yet (Part D/O/P: still capturing
    // Ignition's full depth/cull state-setup block before mapping any of
    // it to vitaGL).
    uint32_t depth_mask = 0;   // FxBool
    // iteration-G8: GrCmpFnc_t written by grDepthBufferFunction -- logical
    // state only, no glDepthFunc() call performed yet (Part E/Q: still
    // capturing Ignition's full depth/cull state-setup block before
    // mapping any of it to vitaGL).
    uint32_t depth_function = 0;   // GrCmpFnc_t
    // iteration-G9: GrCullMode_t written by grCullMode -- logical state
    // only, no glEnable/glDisable(GL_CULL_FACE)/glCullFace() call performed
    // yet (Part E/Q: still capturing Ignition's full depth/cull state-setup
    // block before mapping any of it to vitaGL).
    uint32_t cull_mode = 0;   // GrCullMode_t
    // iteration-G12: logical clip rectangle written by grClipWindow --
    // bounds as Glide passed them (minx/miny inclusive, maxx/maxy
    // exclusive per Glide's standard width=maxx-minx convention), in
    // LOGICAL (640x400-space) coordinates, not yet converted to physical.
    uint32_t clip_min_x = 0;
    uint32_t clip_min_y = 0;
    uint32_t clip_max_x = 0;
    uint32_t clip_max_y = 0;
    // iteration-G13: GrTexTable_t/data written by grTexDownloadTable --
    // logical storage only, no glTexImage2D/glBindTexture yet (Part H: no
    // texture is created by this call alone -- deferred until
    // guTexDownloadMipMap/guTexSource show how Ignition actually binds a
    // texture to this table).
    uint32_t tex_table_type = 0;      // GrTexTable_t
    bool     palette_valid = false;
    uint32_t palette[256] = {};       // GR_TEXTABLE_PALETTE entries, raw
                                       // 32-bit Glide-encoded colors, not
                                       // yet converted to any GL format

    // iteration-G17: logical texture-memory allocator state reset by
    // guTexMemReset() -- the "gu" utility layer's own free-memory
    // bookkeeping for texture uploads (used internally by
    // guTexAllocateMemory), NOT immediate GPU resource destruction and
    // NOT the palette (grTexDownloadTable's own, separate subsystem --
    // Part F, verified: guTexMemReset does not invalidate palette state
    // in Glide 2.x's documented semantics).
    uint32_t tex_mem_next_address = 0;
    uint32_t tex_mem_allocation_count = 0;
    uint32_t tex_mem_generation = 0;

    // iteration-G18: LFB (linear framebuffer) shadow buffer state --
    // allocated ONCE (permanent, per ignition_guest_alloc_pixels's own
    // contract -- see runtime/ignition_guest_alloc.h) and reused across
    // repeated grLfbLock/grLfbUnlock cycles, not re-allocated per lock.
    // Sized to the LOGICAL Glide resolution (width/height above, 640x400),
    // not the Vita's physical 960x544 -- Glide's own LFB coordinate space
    // is the logical screen, matching grClipWindow's own logical
    // coordinates; upscaling to the physical display is vitaGL's/
    // present-time concern, not the LFB's.
    uint32_t lfb_shadow_ptr = 0;         // guest address, 0 = not yet allocated
    uint32_t lfb_shadow_size = 0;        // bytes
    uint32_t lfb_stride_bytes = 0;
    bool     lfb_locked = false;
    uint32_t lfb_lock_type = 0;          // GrLock_t at the most recent lock
    uint32_t lfb_write_mode = 0;         // GrLfbWriteMode_t at the most recent lock
    uint32_t lfb_checksum_at_lock = 0;   // Parte Y: dirty-tracking baseline

    // iteration-G19: LFB -> vitaGL texture upload state. The texture
    // object itself is created ONCE (Part H) and reused via
    // glTexSubImage2D on subsequent unlocks -- never recreated per
    // unlock. lfb_texture is a raw GLuint value (uint32_t here so this
    // struct definition compiles unconditionally for both renderer
    // branches -- see G4's original note on why GL types stay out of
    // unconditionally-compiled code).
    uint32_t lfb_texture = 0;
    bool     lfb_texture_initialized = false;
    // Set by grLfbUnlock, cleared by grBufferSwap right after blitting
    // (Part N/O) -- decouples "guest finished writing" from "presented."
    bool     lfb_dirty = false;

    // iteration-G41, Parte F: guColorCombineFunction's translated logical
    // state -- the SAME four-dimension state grColorCombine itself would
    // set (GrCombineFunction_t/GrCombineFactor_t/GrCombineLocal_t/
    // GrCombineOther_t/invert), even though Ignition never imports
    // grColorCombine directly (confirmed absent from
    // audit/ign_3dfx_imports.txt, Part E) -- guColorCombineFunction is
    // the ONLY entry point that ever sets this. Part I: logical state
    // only, no GL call here -- applied later once a real draw path needs
    // it. color_combine_fnc_raw keeps the original un-translated
    // GrColorCombineFnc_t value for logging/debugging.
    uint32_t color_combine_fnc_raw = 0;
    uint32_t color_combine_function = 0;
    uint32_t color_combine_factor = 0;
    uint32_t color_combine_local = 0;
    uint32_t color_combine_other = 0;
    bool     color_combine_invert = false;
    bool     color_combine_valid = false;

    // iteration-G45, Parte 10: guAlphaSource's translated logical state --
    // the SAME 5-tuple shape guColorCombineFunction already uses (Part
    // 27), since guAlphaSource is a real Glide GU utility that forwards
    // to grAlphaCombine (same 5 params as grColorCombine), NOT imported
    // directly by Ignition (confirmed absent from
    // audit/ign_3dfx_imports.txt, same as grColorCombine in G41).
    uint32_t alpha_source_mode = 0;      // raw GrAlphaSource_t
    uint32_t alpha_combine_function = 0;
    uint32_t alpha_combine_factor = 0;
    uint32_t alpha_combine_local = 0;
    uint32_t alpha_combine_other = 0;
    bool     alpha_combine_invert = false;
    bool     alpha_combine_valid = false;

    // iteration-G46, Parte 9: grConstantColorValue's logical state.
    // Decoded channels (0-255 each) are stored alongside the raw value
    // since GR_COLORCOMBINE_CCRGB/GR_ALPHASOURCE_CC_ALPHA (both already
    // observed real, G41/G45) are exactly the consumers that would need
    // them once a draw path actually applies this state (Part 9: "solo
    // si ya se usan en draw" -- decoded now because the decode itself is
    // the whole point of this iteration, not speculative).
    bool     constant_color_valid = false;
    uint32_t constant_color_value = 0;   // raw GrColor_t
    uint8_t  constant_color_r = 0;
    uint8_t  constant_color_g = 0;
    uint8_t  constant_color_b = 0;
    uint8_t  constant_color_a = 0;

    // iteration-G43, Parte C/D: grChromakeyMode's logical state.
    // chromakey_value is prepared here (architecturally clean, Part D --
    // both fields belong to the same real Glide "chromakey" subsystem)
    // but grChromakeyValue itself is NOT implemented this iteration --
    // still a generic trap, Part D's own explicit instruction not to
    // preempt it.
    bool     chromakey_enabled = false;
    uint32_t chromakey_value = 0;   // GrColor_t, set only once grChromakeyValue is implemented

    // iteration-G44, Parte D: grAlphaBlendFunction's logical state --
    // raw GrAlphaBlendFnc_t values (not yet translated to GL enums, so
    // this struct doesn't need a GL type even though it compiles
    // unconditionally for both renderer branches).
    bool     alpha_blend_valid = false;
    uint32_t alpha_blend_rgb_src = 0;
    uint32_t alpha_blend_rgb_dst = 0;
    uint32_t alpha_blend_alpha_src = 0;
    uint32_t alpha_blend_alpha_dst = 0;

    // iteration-G77, Parte 8: guTexSource's logical state -- which
    // allocation (Part G's GuTextureAllocation handle) is currently bound
    // as TMU0's source, and the resolved host GL texture id to bind at
    // draw time. texture_source_valid is false until the FIRST real
    // guTexSource call succeeds (Part 9: never bind texture 0 silently).
    bool     texture_source_valid = false;
    uint32_t current_texture_mmid = 0;
    uint32_t current_texture_gl_id = 0;

    // iteration-G77, Parte 10/11: guTexCombineFunction's logical state --
    // raw GrTextureCombineFnc_t plus whether it decoded to a translation
    // this project has real-hardware/real-disassembly evidence for (Parte
    // 7's own evidenced call site: guTexCombineFunction(tmu=0, fnc=0x1)).
    bool     tex_combine_valid = false;
    uint32_t tex_combine_fnc_raw = 0;
};
GlideContext g_glideContext;

// iteration-G39, Parte F/G: logical guTexAllocateMemory bookkeeping.
// Exactly the fields this project's own real disassembled call actually
// needs (Parte G: "no sobrediseñar") -- every field here is one of the
// 15 real guTexAllocateMemory arguments this iteration confirmed against
// openglide's sdk2_glide.h (a real, historically shipped Glide 2.x
// header; license: see the notice at the top of this file -- semantics-only
// reuse of its interface facts, same citation status as the NFSIISE
// citations), plus the computed byte size and a generation stamp so
// guTexMemReset (Parte P) can invalidate every outstanding handle without
// physically erasing the map. Deliberately NOT a GL texture yet (Parte H)
// -- no GLuint field here; that's created later, by guTexDownloadMipMap/
// guTexSource, once real pixel content actually exists to upload.
struct GuTextureAllocation {
    uint32_t handle = 0;
    uint32_t tmu = 0;              // GrChipID_t
    uint32_t oddEvenMask = 0;      // FxU8, widened
    uint32_t width = 0;
    uint32_t height = 0;
    uint32_t format = 0;           // GrTextureFormat_t
    uint32_t mmMode = 0;           // GrMipMapMode_t
    uint32_t smallLod = 0;         // GrLOD_t
    uint32_t largeLod = 0;         // GrLOD_t
    uint32_t aspect = 0;           // GrAspectRatio_t
    uint32_t sClampMode = 0;       // GrTextureClampMode_t
    uint32_t tClampMode = 0;       // GrTextureClampMode_t
    uint32_t minFilterMode = 0;    // GrTextureFilterMode_t
    uint32_t magFilterMode = 0;    // GrTextureFilterMode_t
    uint32_t lodBiasBits = 0;      // float, raw bit pattern (not decoded -- unused until real filtering exists)
    uint32_t trilinear = 0;        // FxBool
    uint32_t memRequiredBytes = 0; // computed, Parte I
    uint32_t generation = 0;       // matched against g_glideContext.tex_mem_generation at lookup time

    // iteration-G40, Parte T: added only because guTexDownloadMipMap
    // (this iteration) is the real upload point -- no speculative fields.
    // glTextureId is a raw GLuint value stored as uint32_t (same reason
    // as g_glideContext.lfb_texture: this struct compiles unconditionally
    // for both renderer branches, see G4's original note).
    bool     sourceUploaded = false;
    uint32_t glTextureId = 0;

    // iteration-G94: diagnostic identity only.  The signature is sampled
    // while the decoded CPU upload buffer already exists; no guest pointer
    // is retained and the texture/upload path is otherwise unchanged.
    uint32_t g94CoarseSignature = 0;
    uint32_t g94UploadGeneration = 0;
    uint32_t g94LastTexSourceCaller = 0;

    // iteration-G89, Parte 8/16: MMID_ABI_DIVERGENCE=PROVEN this iteration
    // by direct native-oracle measurement (pc_oracle_log.txt, the user's
    // own real Ign_3dfx.exe + real glide2x.dll): native guTexAllocateMemory
    // returns small values (observed 0x00-0x1C, 86/86 samples <256) and
    // the game passes them back to guTexSource UNCHANGED (128/128 exact
    // matches, [G88-NATIVE-MMID-CORRELATION]). `handle` above is now the
    // small, native-compatible, guest-visible GrMipMapId_t (0,1,2,...).
    // The OLD 0x70000001+N numbering this project used through G88 is kept
    // here ONLY as a private, never-guest-visible debug id, so older log
    // lines/investigations that reference "0x700000xx" style values stay
    // traceable to a specific allocation record.
    uint32_t internalDebugId = 0;
    // G155-BEGIN
    // iteration-G155: what the chroma key needs of a texture (win32/g155_keyfast.h). The game's remap loop (0x0044FE70) translates a 256x256 palette-index image into the RGB332 image that is downloaded; the translation table of
    // that download is kept (256 B), the index image only when the texture has a texel that can be keyed, and the per-texture decision / variant state (indices used, content generation and digest, selection the variant was built for).
    std::vector<uint8_t> g155Idx; uint8_t g155Xlat[256] = {}; ign::g155::TexKey2 g155;
    // G155-END
};

// Same "static local map behind a function" pattern kernel32_ign.cpp's
// g_findHandles() uses -- avoids a second global-init-order-dependent
// object at namespace scope.
std::map<uint32_t, GuTextureAllocation>& gu_tex_allocations() {
    static std::map<uint32_t, GuTextureAllocation> m;
    return m;
}

// iteration-G89, Parte 6-11: replaces next_gu_tex_handle()'s old
// 0x70000001+N scheme. Plain globals (not a function-local static)
// because reset_guest_mmid_allocator() below needs to restart the
// sequence from guTexMemReset_impl, matching native's own observed
// allocation-cycle/reset behavior (Part 9's own explicit instruction not
// to assume unbounded monotonic growth forever). 0x00 is a valid,
// non-sentinel guest MMID -- confirmed by the native oracle itself
// observing it as a real allocation return -- GR_NULL_MIPMAP_HANDLE stays
// the unrelated 0xFFFFFFFF failure sentinel, unambiguous either way.
uint32_t g_g89NextGuestMmid = 0;
uint32_t g_g89NextInternalDebugId = 0x70000001u;

uint32_t next_guest_mmid() {
    return g_g89NextGuestMmid++;
}
// iteration-G89, Parte 16: internal-only counter, never guest-visible,
// never used for any lookup -- exists purely so a log line can still name
// "which allocation" without exposing the old namespace to the guest.
uint32_t next_gu_tex_internal_debug_id() {
    return g_g89NextInternalDebugId++;
}
// iteration-G89, Parte 15: called from guTexMemReset_impl. Only the
// guest-visible MMID sequence restarts -- the internal debug id keeps
// counting across the whole process lifetime (distinguishing allocation
// GENERATIONS even across a guest-visible reset, same spirit as the
// existing tex_mem_generation stamp).
void reset_guest_mmid_allocator() {
    g_g89NextGuestMmid = 0;
}

// GrScreenResolution_t -> pixel size. Table taken from NFSIISE's Glide2x.h
// (MIT-licensed, semantics-only reuse -- audit/NFS2_GLIDE_REFERENCE.md
// chapter on licensing). Only 0x6 (640x400) is proven to be what Ignition
// actually requests (confirmed by G3's real-hardware log); the rest are
// filled in from the same reference table so this helper doesn't need to
// grow later for a resolution we simply haven't seen requested yet.
bool gr_resolution_to_size(uint32_t resolution, int& widthOut, int& heightOut) {
    switch (resolution) {
        case 0x0: widthOut = 320; heightOut = 200; return true;  // GR_RESOLUTION_320x200
        case 0x1: widthOut = 320; heightOut = 240; return true;  // GR_RESOLUTION_320x240
        case 0x2: widthOut = 400; heightOut = 256; return true;  // GR_RESOLUTION_400x256
        case 0x3: widthOut = 512; heightOut = 384; return true;  // GR_RESOLUTION_512x384
        case 0x4: widthOut = 640; heightOut = 200; return true;  // GR_RESOLUTION_640x200
        case 0x5: widthOut = 640; heightOut = 350; return true;  // GR_RESOLUTION_640x350
        case 0x6: widthOut = 640; heightOut = 400; return true;  // GR_RESOLUTION_640x400 (PROVEN: what Ignition requests)
        case 0x7: widthOut = 640; heightOut = 480; return true;  // GR_RESOLUTION_640x480
        case 0x8: widthOut = 800; heightOut = 600; return true;  // GR_RESOLUTION_800x600
        case 0x9: widthOut = 960; heightOut = 720; return true;  // GR_RESOLUTION_960x720
        case 0xa: widthOut = 856; heightOut = 480; return true;  // GR_RESOLUTION_856x480
        case 0xb: widthOut = 512; heightOut = 256; return true;  // GR_RESOLUTION_512x256
        default:  widthOut = 0;   heightOut = 0;   return false;
    }
}

// iteration-G11, Parte "NUEVA POLITICA DE TRAPS": grGlideInit through
// grBufferSwap are now all real implementations that RETURN to the guest
// normally, so kGlideFns[] (below) only ever lists imports that have
// genuinely never been implemented -- the generic trap therefore already,
// structurally, only fires on the first call to an API this bring-up has
// never handled, regardless of how many times already-implemented calls
// (e.g. grBufferClear/grBufferSwap in a frame loop) repeat first. This
// flag/name only tracks whether THAT trap has already fired once (so a
// second, spurious guest call after halt was requested doesn't re-log a
// duplicate "first hit" line) -- it is not an ordinal call counter.
bool g_nextUnimplementedGlideCallLogged = false;

// iteration-G11: monotonic counter incremented on EVERY Glide call this
// bring-up observes -- implemented or trapped alike (incremented inside
// read_caller_eip, which every _impl/trap function below calls first) --
// so log lines can show "this is call #14 overall" even once
// grBufferClear/grBufferSwap start repeating in a frame loop and the
// ordinal-numbered-call-per-iteration naming (FIRST_GLIDE_CALL..
// ELEVENTH_GLIDE_CALL) stops being meaningful.
uint32_t g_glideRuntimeCallIndex = 0;

// iteration-G31, Parte L/P/Q/S: per-swap-interval counters and wall-clock
// cost accumulators, reset every grBufferSwap right after being logged --
// answers PARTE O's own caution ("no asumir que es rendimiento sin medir")
// with real numbers instead of a guess either way. Declared UNCONDITIONALLY
