struct G98TimelineEvent { const char* kind; uint32_t caller,swap,count; };
constexpr int kG98MaxTimelineEvents=256; G98TimelineEvent g_g98Timeline[kG98MaxTimelineEvents]; int g_g98TimelineCount=0; bool g_g98TimelineCaptureEnabled=false;
void g98_timeline(const char* kind,uint32_t caller=0){if(!g_g98TimelineCaptureEnabled)return;if(g_g98TimelineCount>0&&strcmp(g_g98Timeline[g_g98TimelineCount-1].kind,kind)==0&&g_g98Timeline[g_g98TimelineCount-1].caller==caller){++g_g98Timeline[g_g98TimelineCount-1].count;return;}if(g_g98TimelineCount<kG98MaxTimelineEvents)g_g98Timeline[g_g98TimelineCount++]={kind,caller,(uint32_t)g_completedSwapCount,1};}
void g98_log_state_change(const char* api, uint32_t caller, uint32_t oldValue, uint32_t newValue) {
    if (g_g98StateCaptureEnabled && oldValue != newValue && g_g98StateEventCount<kG98MaxStateEvents) {
        g_g98StateEvents[g_g98StateEventCount++]={api,caller,oldValue,newValue,(uint32_t)g_completedSwapCount};
        g98_timeline("STATE_CHANGE",caller);
    }
}
constexpr int kDetailedLogCycles = 4;

// ---- iteration-G125: car-selection carousel drawn AFTER the LFB compositor (selection node only) ----
// What G118-G124 proved (hardware logs, treated as data) and this build keeps:
//  * The carousel cars are TEXTURED triangles issued by the render-list dispatcher 0x0044FF20 when it is called from 0x00409940 (dispatcher return
//    address 0x00409AA0, five cars per frame); the animated 3D background is a different dispatcher call (return 0x00409B77) and 0x00450DEF is just a
//    generic flat primitive used by that background. Guest frame order is: background -> LFB (menu buffer flush, 3 lock/unlock pairs) -> cars -> LFB (4 pairs).
//  * The port composes "all 3D, then all LFB", so the opaque LFB panel under the cars hid them. Drawing the car triangles once, after the LFB compositor
//    and right before the present, with their own texture/blend state, makes them visible (G124).
// G125 turns that into the final, clean path:
//  * dynamic scope: the dispatcher's own grClipWindow (return EIP 0x0044FF98) exposes its return address at ESP+0x24 on the guest stack; every
//    guDrawTriangleWithClip until the next dispatcher start belongs to that list. Only 0x00409AA0 (carousel) is captured, never the background.
//  * each captured triangle is copied once into a fixed buffer instead of being drawn in the 3D pass (so it is never drawn twice), and replayed after the
//    compositor, batched by identical texture/blend, in the original order. The buffer is emptied every present and whenever the selection node is left.
//  * the LFB writes the guest issues AFTER the cars (4 lock/unlock pairs: UI that sits above the cars on the original) are found by comparing the LFB shadow
//    with a copy taken at the first car triangle; only those pixels are drawn again, over the cars, through a second RGBA5551 overlay texture (alpha test, same
//    NEAREST/CLAMP parameters as the existing overlay).
//  * every GL state the replay and the post-car overlay touch is saved and restored by a scope guard (also on early returns). The texture parameters
//    (filters / wrap) are never written by either: the only glTexParameteri calls in this file are the creation sites of the textures. This vitaGL has no
//    glGetTexParameter*, so the filters cannot be queried; they are guaranteed by construction instead.
// Nothing here runs outside the selection node except one bool test per triangle / dispatcher start / present and one guest read per swap.
constexpr uint32_t kG125CarListRet = 0x00409AA0u, kG125DispatchClipRet = 0x0044FF98u;
constexpr int kG125MaxRec = 1536;   // G124 maximum observed in the car scope: 340 triangles per frame (4 cars)
// Pure, GL-free helpers of the post-car overlay (host-tested by tests_host/g125_test.sh).
// Pixels the guest wrote after the cars = pixels that differ from the shadow copy taken at the first car triangle and are not the overlay key.
// `post` (W*H RGBA5551) receives them with alpha 1; `tiles` (40x25, 16x16 logical) marks the touched tiles; r0/r1 = first/last touched row (-1 = none).
inline uint32_t g125_build_post(const uint8_t* cur, const uint8_t* snap, uint32_t stride, int W, int H, uint16_t key, uint16_t* post, bool* tiles, int& r0, int& r1) {
    uint32_t px = 0; r0 = r1 = -1;
    for (int y = 0; y < H; ++y) {
        const uint8_t* a = cur + (size_t)y * stride; const uint8_t* b = snap + (size_t)y * stride;
        if (memcmp(a, b, (size_t)W * 2u) == 0) { continue; }
        for (int x = 0; x < W; ++x) {
            uint16_t v, s0; memcpy(&v, a + x * 2, 2); memcpy(&s0, b + x * 2, 2);
            if (v == s0 || ign::g113::is_key(v, key, ign::g113::kKeyMask)) { continue; }
            post[(size_t)y * (size_t)W + (size_t)x] = ign::g113::rgb565_to_5551(v, true);
            tiles[(y / 16) * 40 + (x / 16)] = true;
            if (r0 < 0) { r0 = y; }
            r1 = y; ++px;
        }
    }
    return px;
}
// Rows to upload = rows written now + rows written last frame (they must go back to alpha 0). -1/-1 = nothing to upload.
inline void g125_upload_rows(int prev0, int prev1, int r0, int r1, int& u0, int& u1) {
    u0 = r0; u1 = r1;
    if (prev0 >= 0) {
        u0 = (u0 < 0) ? prev0 : (prev0 < u0 ? prev0 : u0);
        u1 = (u1 < 0) ? prev1 : (prev1 > u1 ? prev1 : u1);
    }
}
