// one state call in 128 and one triangle call in 32 are timed (two clock reads per 128 / 32 calls, no timer per call): the sampled means tell where the scene time goes. RAII so every return path of a handler is covered.
struct G148StTimer { uint64_t t0 = 0; G148StTimer() { if ((++g_g148.p.st.stateCalls & 127u) == 0u) t0 = wx86_now_us(); } ~G148StTimer() { if (t0) { g_g148.p.st.stateSampleUs += wx86_now_us() - t0; ++g_g148.p.st.stateSamples; } } };
struct G148TriTimer { uint64_t t0 = 0; G148TriTimer() { if ((++g_g148.p.st.triCalls & 31u) == 0u) t0 = wx86_now_us(); } ~G148TriTimer() { if (t0) { g_g148.p.st.triSampleUs += wx86_now_us() - t0; ++g_g148.p.st.triSamples; } } };
