// Confirmed guest stack region (established across many earlier
// iterations of this project's DirectDraw work, re-used here since it's a
// property of ignition_memlayout.cpp's layout, not of which guest exe is
// running).
constexpr uint32_t kStackLo = 0x06420000u;
constexpr uint32_t kStackHiExclusive = 0x06620000u;   // 0x0661FFFF + 1

// iteration-G13: Ignition's own PE image maps 1:1 at its preferred VA
// range -- confirmed on real hardware (runtime/ignition_memlayout.h's own
// header comment: "loads at its own fixed preferred base (confirmed on
// real hardware: 0x00400000..0x0066E000)"). Used to validate a STATIC
// data pointer like grTexDownloadTable's table address, which is a
// pointer into Ignition's .data section, NOT a stack address --
// kStackLo/kStackHiExclusive above are specific to Bridge's guest stack
// region and don't apply here.
constexpr uint32_t kPeImageLo = 0x00400000u;
constexpr uint32_t kPeImageHiExclusive = 0x0066E000u;

uint32_t read_caller_eip(Cpu& c, uint32_t& espOut) {
    uint32_t esp = c.reg(R_ESP);
    espOut = esp;
    ++g_glideRuntimeCallIndex;
    return c.read_u32(esp);
}

// iteration-G50, Parte 16/17: a small in-RAM ring of the last
// kG50RingSize Glide state-setting calls (plus the draw call itself,
// caller EIP only -- its full vertex data is already covered by
// gu_log_nonfinite_vertex_dump), dumped exactly once, alongside that
// same existing one-shot dump, when guDrawTriangleWithClip halts on a
// required non-finite field. This is NOT live per-call logging (Part 16
// explicitly forbids that) -- pushes are silent RAM writes; the only log
// output is the one-shot dump below. Lets the NEXT hardware run show
// exactly which color/alpha/texture state calls preceded the failing
// draw and in what order, instead of us statically guessing the state
// machine's history.
//
// iteration-G51, Parte 25: expanded 32->64 entries (still RAM-only, still
// a single one-shot dump, Part 25's own instruction) so a longer state
// history -- including whichever grConstantColorValue call last ran, if
// any -- survives into the dump even on busier runs.
constexpr int kG50RingSize = 64;
struct G50RingEntry { const char* api; uint32_t arg0; uint32_t arg1; uint32_t callerEip; };
G50RingEntry g_g50Ring[kG50RingSize] = {};
int g_g50RingPos = 0;
uint32_t g_g50RingTotalPushed = 0;

void g50_ring_push(const char* api, uint32_t arg0, uint32_t arg1, uint32_t callerEip) {
    g_g50Ring[g_g50RingPos] = G50RingEntry{ api, arg0, arg1, callerEip };
    g_g50RingPos = (g_g50RingPos + 1) % kG50RingSize;
    ++g_g50RingTotalPushed;
}

void g50_ring_dump() {
    uint32_t count = (g_g50RingTotalPushed < (uint32_t)kG50RingSize) ? g_g50RingTotalPushed : (uint32_t)kG50RingSize;
    int start = (g_g50RingTotalPushed < (uint32_t)kG50RingSize) ? 0 : g_g50RingPos;
    IGN_LOG("[G50-PREFAIL-GLIDE]", "ring_entries=%u total_glide_state_calls_seen=%u (oldest first)",
            count, g_g50RingTotalPushed);
    for (uint32_t i = 0; i < count; ++i) {
        int idx = (start + (int)i) % kG50RingSize;
        const G50RingEntry& e = g_g50Ring[idx];
        IGN_LOG("[G50-PREFAIL-GLIDE]", "#-%u api=%s arg0=0x%08x arg1=0x%08x caller=0x%08x",
                count - i, e.api ? e.api : "?", e.arg0, e.arg1, e.callerEip);
    }
}

// iteration-G52, Parte 8/9: ONE low-cost line, fired only from the same
// one-shot failure branch as the existing dumps above (never per-
// primitive, Part 8's own instruction) -- logs the LIVE guest ESI
// register at the exact moment of the trap into guDrawTriangleWithClip.
// Static disassembly of the caller (0x00451f10-0x00452263, see this
// file's G50/G51 comments) shows ESI is loaded once at function entry
// (`mov esi,[esp+0x10c]`, the function's own arg0 -- a pointer field
// read out of the enclosing particle record, `[particle+0x0]`) and is
// used ONLY as a read-only base pointer for the rest of the function
// (every other field access is `[esi+N]`) -- it is never reassigned
// before either guDrawTriangleWithClip call, unlike EDI (repurposed for
// unrelated affine math at 0x00451fd6, which is why THAT register can't
// be trusted here). Standard cdecl/stdcall treats ESI as callee-saved,
// and every helper this function calls preserves it -- so ESI's value at
// this trap should still be that same particle-substructure pointer.
// re-READING [esi+0x18] from guest memory (not the EDI register, which
// IS clobbered) recovers the exact field the fallback-vs-normal branch
// at 0x00451f24-0x00451f2e tested, with only the same order-of-
// operations caveat any static reconstruction carries -- this is
// observation, not a fix; nothing about the branch or the field is
// touched.
void g52_log_path_diagnostic(Cpu& c) {
    uint32_t presumedParticlePtr = c.reg(R_ESI);
    uint32_t typeIndexRaw = c.read_u32(presumedParticlePtr + 0x18);
    IGN_LOG("[G52-PATH]", "caller_function=0x00451F10 branch_eip=0x00451f24/0x00451f28 "
                          "condition_address=0x%08x(esi+0x18) condition_raw=0x%08x "
                          "normal_path_requires=0<=value<0x100 actual_path=FALLBACK_ITRGB "
                          "(esi presumed unclobbered since function entry, Parte 8/9 -- see comment above)",
            presumedParticlePtr + 0x18, typeIndexRaw);
}

// iteration-G56, Parte 9: ONE low-cost line, same one-shot failure branch
// as g52_log_path_diagnostic above -- queries this project's OWN
// GuestRegion heap metadata (block_of()/size_of(), both pre-existing
// public read-only queries on wx86::GuestRegion, not new allocator code)
// for the LIVE status of esi RIGHT NOW, at the exact moment of the
// failing draw, plus this file's own target-range tracking (win32/
// kernel32_ign.cpp's g_g56Target* globals) for the fuller allocation
// history (caller EIP, generation, last free). Answers Part 9's
// [G56-OBJECT-HEAP] request directly from ground truth rather than
// inferring liveness from the value alone.
void g56_log_object_heap_diagnostic(Cpu& c) {
    uint32_t esi = c.reg(R_ESI);
    wx86::GuestRegion& heap = ignition_heap_region();
    uint32_t blockBase = heap.block_of(esi);
    uint32_t blockSize = blockBase ? heap.size_of(blockBase) : 0;
    bool liveNow = (blockBase != 0);
    IGN_LOG("[G56-OBJECT-HEAP]", "esi=0x%08x field=0x%08x live_now=%s block_base=0x%08x block_size=%u "
                                "tracked_alloc_base=0x%08x tracked_alloc_size=%u tracked_generation=%u "
                                "tracked_alloc_caller=0x%08x tracked_live=%s",
            esi, esi + 0x18, liveNow ? "YES" : "NO", blockBase, blockSize,
            g_g56TargetAllocBase, g_g56TargetAllocSize, g_g56TargetGeneration,
            g_g56TargetAllocCallerEip, g_g56TargetLive ? "YES" : "NO");
    if (!liveNow) {
        IGN_LOG("[G56-UAF]", "PROVEN=YES esi=0x%08x is NOT inside any currently-live heap allocation at draw time", esi);
    }
}

