uint32_t grGlideInit_impl(Cpu& c) {
    uint32_t esp = 0;
    uint32_t callerEip = read_caller_eip(c, esp);
    g_glideState.initialized = true;
    IGN_LOG("[GLIDE-G1]", "grGlideInit() caller_guest_eip=0x%08x guest_esp=0x%08x", callerEip, esp);
    IGN_LOG("[GLIDE-G1]", "initialized=1");
#ifdef IGNITION_RENDERER_3DFX
    g71_selftest();   // one-shot, host-side only, never halts on failure -- see its own definition
    g72_log_family_audit();   // one-shot static knowledge, see its own definition
    g73_log_native_nan_semantics();   // one-shot static knowledge + experiment citation, see its own definition
    g75_log_native_channel_semantics();   // one-shot static knowledge + experiment citation, see its own definition
    g76_log_spam_audit();   // one-shot static knowledge, see its own definition
    g75_selftest();   // one-shot, host-side only, never halts on failure -- see its own definition
#endif
    return 0;
}

// GrHwConfiguration layout (Glide 2.x, GLIDE_NUM_TMU=2 -- the SDK's own
// default, confirmed as the value NFSIISE's independently-written headers
// use too; not verified against Ignition's own compiled constant, but the
// disassembly below only ever touches TMU/board index 0, so this doesn't
// matter for reaching THIRD_GLIDE_CALL either way):
//   int num_sst;                                  offset 0
//   struct { GrSstType type; union { ... } sstBoard; } SSTs[MAX_NUM_SST=4];
//     each entry: type @ +0, sstBoard union @ +4, union size = 32
//     (GrVoodooConfig_t is the largest member: fbRam,fbiRev,nTexelfx,
//      sliDetect = 4 ints, + tmuConfig[2] * {tmuRev,tmuRam} = 2*8 = 16;
//      4*4+16=32), so each SSTs[] entry is 36 bytes.
// Total = 4 + 4*36 = 148 bytes.
constexpr uint32_t OFF_NUM_SST   = 0;
constexpr uint32_t OFF_SSTS      = 4;
constexpr uint32_t SST_ENTRY_SZ  = 36;
constexpr uint32_t OFF_SST0_TYPE = OFF_SSTS + 0;             // 4
constexpr uint32_t OFF_SST0_BOARD= OFF_SSTS + 4;             // 8
constexpr uint32_t OFF_VOODOO_FBRAM     = OFF_SST0_BOARD + 0;   // 8
constexpr uint32_t OFF_VOODOO_FBIREV    = OFF_SST0_BOARD + 4;   // 12  (0xC)
constexpr uint32_t OFF_VOODOO_NTEXELFX  = OFF_SST0_BOARD + 8;   // 16
constexpr uint32_t OFF_VOODOO_SLIDETECT = OFF_SST0_BOARD + 12;  // 20
constexpr uint32_t OFF_VOODOO_TMU0_REV  = OFF_SST0_BOARD + 16;  // 24
constexpr uint32_t OFF_VOODOO_TMU0_RAM  = OFF_SST0_BOARD + 20;  // 28
constexpr uint32_t STRUCT_SIZE = 4 + 4 * SST_ENTRY_SZ;        // 148

uint32_t grSstQueryHardware_impl(Cpu& c) {
    uint32_t esp = 0;
    uint32_t callerEip = read_caller_eip(c, esp);
    uint32_t ptr = c.arg(0);

    IGN_LOG("[GLIDE-HW-G2]", "grSstQueryHardware(ptr=0x%08x) caller_guest_eip=0x%08x guest_esp=0x%08x struct_size=%u",
            ptr, callerEip, esp, STRUCT_SIZE);

    // Part D: expected post-return ESP for a stdcall function with 1 dword
    // arg -- return-address pop (4) + callee's own arg cleanup (4) = 8.
    // Logged, not verified by a second read: Bridge's trap_epilogue is the
    // same mechanism every other shim in this project already trusts (100+
    // working shims), not something this iteration re-implements or checks
    // independently.
    IGN_LOG("[GLIDE-HW-G2]", "stack_check: entry_esp=0x%08x argc_dwords=1 expected_esp_after_return=0x%08x (entry_esp+8, stdcall @4 cleanup)",
            esp, esp + 8);

    bool mapped = (ptr >= kStackLo) && (ptr <= kStackHiExclusive) && ((uint64_t)ptr + STRUCT_SIZE <= kStackHiExclusive);
    IGN_LOG("[GLIDE-HW-G2]", "mapped=%s (guest stack region 0x%08x-0x%08x)", mapped ? "yes" : "no", kStackLo, kStackHiExclusive - 1);

    // Dump BEFORE writing anything -- Part A section 4. This is whatever
    // garbage/prior-frame data already sits in that stack slice; purely
    // diagnostic, never interpreted.
    {
        char dumpBuf[16 * 12 + 1];
        size_t pos = 0;
        dumpBuf[0] = '\0';
        uint32_t dumpWords = mapped ? 16u : 0u;   // 64 bytes / 4
        for (uint32_t i = 0; i < dumpWords && pos < sizeof(dumpBuf) - 12; ++i) {
            uint32_t v = c.read_u32(ptr + i * 4);
            int n = snprintf(dumpBuf + pos, sizeof(dumpBuf) - pos, "%s%08x", i ? " " : "", v);
            if (n > 0) pos += (size_t)n;
        }
        IGN_LOG("[GLIDE-HW-G2]", "before_write (first 64 bytes as dwords): %s", dumpWords ? dumpBuf : "(skipped, not mapped)");
    }

    if (!mapped) {
        IGN_LOG("[GLIDE-HW-G2]", "ABORT: hwconfig pointer 0x%08x + %u bytes does not fit in the known guest stack region -- refusing to write blindly", ptr, STRUCT_SIZE);
        request_halt("G2: grSstQueryHardware's hwconfig pointer is outside the expected guest stack region");
        return 0;
    }

    // Zero the whole struct first -- every field the game might read
    // later (even ones not proven read in the disassembly window covered
    // this iteration) gets a defined, non-garbage value, not stack noise.
    for (uint32_t off = 0; off < STRUCT_SIZE; off += 4) c.write_u32(ptr + off, 0);

    // Fields PROVEN read by Ignition's own code, disassembled this
    // iteration (0x0045868A-0x004586AB): after grSstQueryHardware returns
    // non-zero, Ignition reads [hwconfig+4] (SSTs[0].type) and, only if
    // that equals GR_SSTTYPE_VOODOO(0), reads [hwconfig+0xC]
    // (SSTs[0].sstBoard.VoodooConfig.fbiRev) and compares it to 1,
    // storing a boolean classification flag into a global at 0x0061EB20.
    // fbiRev=1 is chosen because it's the EXACT value Ignition's own code
    // compares against (not an assumption) -- it selects the "normal"
    // (flag=0/false) path rather than whatever special-case the other
    // branch handles, which hasn't been investigated yet.
    c.write_u32(ptr + OFF_NUM_SST, 1);                 // one virtual board -- not proven read in this window, but a reasonable minimum (section 9: "one board, one SST, one TMU")
    c.write_u32(ptr + OFF_SST0_TYPE, 0);               // GR_SSTTYPE_VOODOO
    c.write_u32(ptr + OFF_VOODOO_FBIREV, 1);           // PROVEN read + compared; this exact value takes the flag=0 path

    // Fields NOT proven read in this iteration's disassembly window --
    // filled with plausible, non-garbage defaults only so nothing reads
    // raw stack noise if a LATER Glide call inspects them. Explicitly
    // logged as defensive, not evidence-based.
    c.write_u32(ptr + OFF_VOODOO_FBRAM, 2);            // 2 MB framebuffer -- common Voodoo1/2 config, NOT proven
    c.write_u32(ptr + OFF_VOODOO_NTEXELFX, 1);         // one TMU chip -- NOT proven
    c.write_u32(ptr + OFF_VOODOO_SLIDETECT, 0);        // FALSE (not SLI) -- NOT proven
    c.write_u32(ptr + OFF_VOODOO_TMU0_REV, 1);         // NOT proven
    c.write_u32(ptr + OFF_VOODOO_TMU0_RAM, 2);         // 2 MB -- NOT proven

    IGN_LOG("[GLIDE-HW-G2]", "configuration written: num_sst=1 SSTs[0].type=GR_SSTTYPE_VOODOO(0) "
            "VoodooConfig.fbiRev=1(PROVEN read+compared) fbRam=2 nTexelfx=1 sliDetect=0 tmuConfig[0]={tmuRev=1,tmuRam=2} "
            "(fbRam/nTexelfx/sliDetect/tmuConfig defensive defaults, not proven read this iteration)");

    g_glideState.hwQueried = true;
    IGN_LOG("[GLIDE-HW-G2]", "return=FXTRUE(1)");
    return 1;   // FXTRUE
}

// grSstSelect(int which_sst) -- void, 1 dword arg, decorated
// _grSstSelect@4. Confirmed by real hardware (G2's log) that Ignition
// calls this with which_sst=0, consistent with the num_sst=1 we wrote in
// grSstQueryHardware's response -- the only virtual board we've told the
// guest exists. This is a logical selection only: no GPU/vitaGL context,
// no buffers, exactly per this iteration's Part A section 2.
uint32_t grSstSelect_impl(Cpu& c) {
    uint32_t esp = 0;
    uint32_t callerEip = read_caller_eip(c, esp);
    int32_t whichSst = (int32_t)c.arg(0);

    IGN_LOG("[GLIDE-G3]", "grSstSelect(which_sst=%d) caller_guest_eip=0x%08x guest_esp=0x%08x", whichSst, callerEip, esp);
    IGN_LOG("[GLIDE-G3]", "stack_check: entry_esp=0x%08x argc_dwords=1 expected_esp_after_return=0x%08x",
            esp, esp + 8);

    if (whichSst < 0 || whichSst >= GlideState::kNumSst) {
        IGN_LOG("[GLIDE-G3]", "ABORT: which_sst=%d is outside the valid range [0,%d) for our num_sst=%d virtual configuration",
                whichSst, GlideState::kNumSst, GlideState::kNumSst);
        request_halt("G3: grSstSelect called with an out-of-range which_sst for our num_sst=1 virtual hwconfig");
        return 0;
    }

    g_glideState.sstSelected = true;
    g_glideState.selectedSst = whichSst;
    IGN_LOG("[GLIDE-G3]", "selected_sst=%d", g_glideState.selectedSst);
    return 0;   // void function: EAX is don't-care.
}

#ifdef IGNITION_RENDERER_3DFX
// iteration-G4C, Parte A/B/C/D: G4B's "return==GL_FALSE means failure"
// premise was WRONG, and this iteration re-derived the real semantics
// from the EXACT revision actually linked into this VPK, not from
// "master" or generic docs:
//   - installed libvitaGL.a/vitaGL.h timestamp: 2026-04-25 09:23:14
//     (checked via `Get-Item` on both files in
//     /usr/local/vitasdk/arm-vita-eabi/{lib,include}).
//   - the vitaGL source checkout (vendored full source checkout on this machine,
//     Rinnegatamante's own repo) commit c5d2ad6 ("Add vglLazyFree
//     function", 2026-04-22) is the closest commit before that install
//     date; the very next commit affecting vgl.c is e9ba795 (2026-04-28,
//     splashscreen feature, unrelated to init return semantics).
//   - `git show c5d2ad6:source/vgl.c` was read directly (not HEAD) to
//     confirm this is truly the revision in question -- its
//     vglInitWithCustomSizes() is byte-identical, in the relevant region,
//     to HEAD's.
// Reading that function's full body: `GLboolean res_fallback = GL_FALSE;`
// is set to GL_TRUE ONLY if the requested width/height exceed
// `sceDisplayGetMaximumFrameBufResolution()`'s result (i.e. a resolution
// fallback/downgrade had to happen), and the function's only two possible
// returns are `return GL_FALSE;` (the already-inited guard, an early
// return before any real work) or, at the very end after a full
// successful init, `return res_fallback;`. So a GL_FALSE at the END of a
// full init (not the early-return path) means "no resolution fallback
// was needed" -- i.e. our requested 960x544 was accepted AS-IS, which is
// the Vita's exact native panel resolution. That is success, not
// failure. G4B's `if (!vglOk) FAIL` logic had this backwards. This is
// exactly why Part F below never trusts the raw return code alone:
// glGetString/glGetError are the real, additional, return-code-independent
// evidence.
void vgl_g4b_log_pre_init(const char* ctx, int legacyPoolSize, int width, int height, int ramThreshold, int msaa) {
    SceUID threadId = sceKernelGetThreadId();
    SceKernelFreeMemorySizeInfo memInfo;
    memInfo.size = sizeof(memInfo);
    int memRc = sceKernelGetFreeMemorySize(&memInfo);
    IGN_LOG("[VGL-G4B]", "%s: thread_id=0x%08x", ctx, (unsigned)threadId);
    if (memRc == 0) {
        IGN_LOG("[VGL-G4B]", "%s: free_mem_before_init: user=%d cdram=%d phycont=%d (bytes)",
                ctx, memInfo.size_user, memInfo.size_cdram, memInfo.size_phycont);
    } else {
        IGN_LOG("[VGL-G4B]", "%s: sceKernelGetFreeMemorySize FAILED rc=0x%08x -- memory info unavailable", ctx, (unsigned)memRc);
    }
    IGN_LOG("[VGL-G4B]", "%s: init begin: vglInitExtended(legacy_pool_size=%d, width=%d, height=%d, ram_threshold=%d/0x%x, msaa=%d)",
            ctx, legacyPoolSize, width, height, ramThreshold, ramThreshold, msaa);
}

// iteration-G4C, Parte F/G/H: the real success signal. `initReturn` is
// logged for the record but NOT used to decide success (see the long
// comment above) -- context validity is established independently via
// glGetString (static strings, always safe to call, confirmed by reading
// get_info.c: no GXM state touched) and glGetError (a plain global-variable
// read/clear, confirmed the same way), then a real clear+swap.
// `tag` is the log tag to use (e.g. "[VGL-G4C]", "[VGL-G4E]") so each
// iteration's call site shows up under its own name while sharing one
// verified implementation -- the verification logic itself doesn't change
// per iteration, only where it's called from.
bool vgl_g4c_verify_context(const char* tag, const char* ctx, GLboolean initReturn) {
    IGN_LOG_DYN(tag, "init_return=%d (%s -- this is a resolution-fallback flag, not success/failure; see G4C's header comment for why)",
            (int)initReturn, initReturn ? "FALLBACK_APPLIED" : "REQUESTED_RESOLUTION_USED_AS-IS");

    const GLubyte* ver = glGetString(GL_VERSION);
    const GLubyte* vendor = glGetString(GL_VENDOR);
    const GLubyte* renderer = glGetString(GL_RENDERER);
    GLenum err = glGetError();

    IGN_LOG_DYN(tag, "GL_VERSION=%s", ver ? (const char*)ver : "(null)");
    IGN_LOG_DYN(tag, "GL_VENDOR=%s", vendor ? (const char*)vendor : "(null)");
    IGN_LOG_DYN(tag, "GL_RENDERER=%s", renderer ? (const char*)renderer : "(null)");
    IGN_LOG_DYN(tag, "glGetError=0x%04x", (unsigned)err);

    bool contextValid = (ver != nullptr) && (vendor != nullptr) && (renderer != nullptr) && (err == 0 /*GL_NO_ERROR*/);
    IGN_LOG_DYN(tag, "%s: context_valid=%s", ctx, contextValid ? "YES" : "NO");
    return contextValid;
}
#endif

// grSstWinOpen(FxU32 hwnd, GrScreenResolution_t resolution,
//   GrScreenRefresh_t refresh, GrColorFormat_t color_format,
//   GrOriginLocation_t origin_location, int numColorBuffers,
//   int numAuxBuffers) -> FxBool. 7 dwords = 28 bytes, decorated
// _grSstWinOpen@28 -- confirmed against Ignition's own real call this
// iteration (G3's hardware log gave FOURTH_GLIDE_CALL=grSstWinOpen with
// these exact 7 args), and disassembly around the call site
// (0x004586C0-0x004586EB) shows: args pushed in reverse-declared order
// (numAuxBuffers, numColorBuffers, origin, color_format, refresh,
// resolution, hwnd), CALL, then `TEST EAX,EAX` / `JZ` on the FxBool
// return -- a plain success/failure branch, not a value comparison, so
// any non-zero return is accepted as success. The fall-through (success)
// path leads directly into what G3 already identified as the next call
// site at 0x004586EB (`PUSH 1`), which is why this iteration keeps that
// as the still-unconfirmed FIFTH_GLIDE_CALL rather than assuming which
// import it resolves to.
#ifdef G104_FRAME_AWARE_LFB_COMPOSITOR
void g113_context_reset();   // iteration-G113, defined with the compositor state further below
#endif
uint32_t grSstWinOpen_impl(Cpu& c) {
    uint32_t esp = 0;
    uint32_t callerEip = read_caller_eip(c, esp);

    uint32_t hwnd            = c.arg(0);
    uint32_t resolution      = c.arg(1);
    uint32_t refresh         = c.arg(2);
    uint32_t colorFormat     = c.arg(3);
    uint32_t origin          = c.arg(4);
    int32_t  numColorBuffers = (int32_t)c.arg(5);
    int32_t  numAuxBuffers   = (int32_t)c.arg(6);

    IGN_LOG("[GLIDE-G4E]", "grSstWinOpen(hwnd=0x%08x, resolution=0x%x, refresh=0x%x, color_format=0x%x, origin=0x%x, numColorBuffers=%d, numAuxBuffers=%d) caller_guest_eip=0x%08x guest_esp=0x%08x",
            hwnd, resolution, refresh, colorFormat, origin, numColorBuffers, numAuxBuffers, callerEip, esp);
#ifdef G104_FRAME_AWARE_LFB_COMPOSITOR
    g113_context_reset();   // iteration-G113: a new Glide context starts with no latched key / armed scene / overlay
#endif
    // Stack/calling-convention check per this iteration's own formula:
    // 7 args * 4 bytes = 28 bytes -> entry_esp + 4 (return address) + 28
    // (stdcall arg cleanup) = entry_esp + 32. Bridge's own trap_epilogue
    // (untouched) is what actually performs this cleanup -- this line only
    // observes/predicts it.
    IGN_LOG("[GLIDE-G4E]", "stack_check: entry_esp=0x%08x argc_dwords=7 expected_esp_after_return=0x%08x (entry_esp+32) return_target=0x%08x (first guest EIP after return, = caller_guest_eip)",
            esp, esp + 32, callerEip);

    // Decode the enums actually observed (G3's log: resolution=6, refresh=0,
    // color_format=0, origin=0, numColorBuffers=2, numAuxBuffers=0) against
    // real Glide 2.x values (NFSIISE's Glide2x.h, semantics-only). Anything
    // outside what's been proven is logged plainly by number, not guessed.
    const char* resName = (resolution == 0x6) ? "GR_RESOLUTION_640x400" : "UNKNOWN";
    const char* refreshName = (refresh == 0x0) ? "GR_REFRESH_60Hz" : "UNKNOWN";
    const char* colorFormatName = (colorFormat == 0x0) ? "GR_COLORFORMAT_ARGB" : "UNKNOWN";
    const char* originName = (origin == 0x0) ? "GR_ORIGIN_UPPER_LEFT" : "UNKNOWN";
    IGN_LOG("[GLIDE-G4E]", "decoded: resolution=%s refresh=%s color_format=%s origin=%s",
            resName, refreshName, colorFormatName, originName);

    int logicalWidth = 0, logicalHeight = 0;
    if (!gr_resolution_to_size(resolution, logicalWidth, logicalHeight)) {
        IGN_LOG("[GLIDE-G4E]", "ABORT: resolution=0x%x is not a known GrScreenResolution_t value -- refusing to guess a framebuffer size", resolution);
        request_halt("G4E: grSstWinOpen called with an unrecognized GrScreenResolution_t");
        return 0;   // FXFALSE
    }

#ifdef IGNITION_RENDERER_3DFX
    // iteration-G4E, Parte A/F: back to initializing vitaGL HERE, once
    // Ignition itself actually asks for a graphics context -- G4D's
    // pre-init in main() (before boot_run()/CpuBox86) coincided with the
    // log dying before "Creating ARM dynarec CPU backend" completed on
    // real hardware, so that early call was removed rather than kept as a
    // guess. This call site is the ONLY vglInitExtended call left in the
    // whole 3dfx build (confirmed by grep after removing glide2x_g4d_preinit_vitagl
    // from main.cpp), so no "already inited" collision is possible.
    //
    // Per this iteration's explicit instruction: init_return is NOT
    // checked as `if (!vglInitExtended(...)) fail` -- G4C proved that
    // pattern is backwards for an exact-fit 960x544 request. Context
    // validity is decided solely by vgl_g4c_verify_context's
    // glGetString/glGetError evidence.
    //
    // iteration-G22, FLAGGED NOT FIXED (frozen architecture, per this
    // iteration's own explicit "no hace falta arreglarla todavía"):
    // vglInitExtended's FIRST parameter is `legacy_pool_size` -- read
    // directly from the exact linked vitaGL revision's source
    // (the vitaGL source checkout, commit c5d2ad6, source/vgl.c's
    // vglInitWithCustomSizes: `legacy_pool_size = pool_size;`, and
    // source/gxm.c: `if (legacy_pool_size) { legacy_pool =
    // gpu_alloc_mapped_temp(legacy_pool_size); legacy_pool_ptr =
    // legacy_pool; ... }` -- i.e. passing 0 here, as this call always
    // has since G4E, means legacy_pool/legacy_pool_ptr are NEVER
    // allocated and legacy_pool_ptr stays NULL for the whole process).
    // source/ffp.c's glVertex3f (called by glVertex2f, called by G19's
    // lfb_blit_to_backbuffer()) unconditionally writes
    // `legacy_pool_ptr[0] = x;` with NO null/bounds check -- a NULL
    // pointer write. This is the CONFIRMED root cause of the crash G19-
    // G22 chased: nothing in this project called glBegin/glVertex*/
    // glTexCoord* before G19, so this latent bug was never triggered
    // until G19's blit became the first immediate-mode draw call ever
    // issued. NOT fixed this iteration on purpose -- the recommended fix
    // for a future iteration is changing this call's first argument from
    // 0 to a nonzero byte count (e.g. a few hundred KB), which is all
    // `legacy_pool_size` needs to be for a single 4-vertex textured
    // quad.
    vgl_g4b_log_pre_init("grSstWinOpen", 0, g_glideContext.physical_width, g_glideContext.physical_height, 6 * 1024 * 1024, SCE_GXM_MULTISAMPLE_4X);
    GLboolean vglInitReturn = g139_vglInitExtended(0, g_glideContext.physical_width, g_glideContext.physical_height, 6 * 1024 * 1024, SCE_GXM_MULTISAMPLE_4X);
    bool vitaglContextValid = vgl_g4c_verify_context("[VGL-G4E]", "grSstWinOpen", vglInitReturn);
    // Parte H: no clear/swap here -- G4C's selftest already proved that
    // path works; this iteration wants Ignition's own real behavior.
    if (!vitaglContextValid) {
        IGN_LOG("[GLIDE-G4E]", "vitaGL context INVALID after init (see [VGL-G4E] lines above for glGetString/glGetError evidence)");
        request_halt("G4E: vitaGL context failed independent verification -- cannot create the first graphics context");
        return 0;   // FXFALSE -- no fake success
    }
    g_glideContext.vitagl_initialized = true;
#endif

    g_glideContext.hwnd             = hwnd;              // stored as-is, incl. 0 -- never substituted
    g_glideContext.resolution       = resolution;
    g_glideContext.refresh          = refresh;
    g_glideContext.color_format     = colorFormat;        // recorded for later use, no ARGB-exact framebuffer yet
    g_glideContext.origin           = origin;              // recorded for later viewport/Y/LFB correction, not applied yet
    g_glideContext.width            = logicalWidth;
    g_glideContext.height           = logicalHeight;
    g_glideContext.num_color_buffers= numColorBuffers;     // 2 observed -- double buffering only, no triple-buffer logic
    g_glideContext.num_aux_buffers  = numAuxBuffers;       // 0 observed -- no depth buffer created by default
    g_glideContext.selected_sst     = g_glideState.selectedSst;
    g_glideContext.window_open      = true;
    g_glideContext.initialized      = true;

    // iteration-G4E, Parte C/E: no glClear/vglSwapBuffers here, and no
    // viewport change -- the selftest already proved the GPU/display path
    // alive; this iteration wants to observe Ignition's REAL behavior, not
    // host-drawn output. The physical viewport vitaGL set up at init time
    // (full 960x544, native) is left as-is; aspect-correct letterboxing
    // for the 640x400 logical content is deferred until a later iteration
    // actually needs to draw something.
    IGN_LOG("[GLIDE-G4E]", "vitaGL context created inside grSstWinOpen");
    IGN_LOG("[GLIDE-G4E]", "physical=%dx%d", g_glideContext.physical_width, g_glideContext.physical_height);
    IGN_LOG("[GLIDE-G4E]", "logical=%dx%d", logicalWidth, logicalHeight);
    IGN_LOG("[GLIDE-G4E]", "origin=%s", originName);
    IGN_LOG("[GLIDE-G4E]", "color_buffers=%d", numColorBuffers);
    IGN_LOG("[GLIDE-G4E]", "aux_buffers=%d", numAuxBuffers);
    IGN_LOG("[GLIDE-G4E]", "grSstWinOpen -> FXTRUE (about to return to guest, return_target=0x%08x)", callerEip);
    return 1;   // FXTRUE
}

// grRenderBuffer(GrBuffer_t buffer) -> void. 1 dword arg, decorated
// _grRenderBuffer@4 -- confirmed against Ignition's own real call this
// iteration (G4E's hardware log gave FIFTH_GLIDE_CALL=grRenderBuffer,
// caller_guest_eip=0x004586f2, arg0=1). Confirmed by direct disassembly +
// import-table cross-reference (not guessed): the call site is
// 0x004586eb (`PUSH 1`) / 0x004586ed (`CALL 0x468c52`); 0x468c52 is a
// standard MSVC IAT jump-thunk (`JMP DWORD PTR [0x46a200]`), and
// 0x0046a200 is glide2x.dll's IAT slot #19, whose import-table name is
// `_grRenderBuffer@4` -- an exact match, and the caller never tests EAX
// after the call (next instruction at 0x4586f2 is `PUSH 0` for the
// following call), confirming a void return. GrBuffer_t=1 decodes to
// GR_BUFFER_BACKBUFFER per Glide's standard, stable public enum
// (GR_BUFFER_FRONTBUFFER=0, GR_BUFFER_BACKBUFFER=1, GR_BUFFER_AUXBUFFER=2
// -- unchanged across every Glide 2.x/3.x reference this project has ever
// consulted; no local Glide2x.h is vendored in this checkout to re-grep
// this session, so this is cited as well-established public API
// knowledge, not re-verified against a local file this iteration).
uint32_t grRenderBuffer_impl(Cpu& c) {
    uint32_t esp = 0;
    uint32_t callerEip = read_caller_eip(c, esp);
    uint32_t buffer = c.arg(0);

    const char* bufferName = nullptr;
    switch (buffer) {
        case 0: bufferName = "GR_BUFFER_FRONTBUFFER"; break;
        case 1: bufferName = "GR_BUFFER_BACKBUFFER";  break;
        case 2: bufferName = "GR_BUFFER_AUXBUFFER";   break;
        default: bufferName = nullptr; break;
    }
    if (!bufferName) {
        IGN_LOG("[GLIDE-G5]", "ABORT: buffer=0x%x is not a known GrBuffer_t value -- refusing to guess", buffer);
        request_halt("G5: grRenderBuffer called with an unrecognized GrBuffer_t");
        return 0;
    }

    // iteration-G81, Parte 22/23: [GLIDE-G5] used to log 4-5 UNCONDITIONAL
    // lines on EVERY call, never gated -- fixed to STATE-TRANSITION-ONLY
    // (Part 22's own explicit request), plus the specific FRONTBUFFER
    // audit Part 23 asks for (never silently mapped to the same buffer as
    // BACKBUFFER -- g_glideContext.render_buffer just records whatever
    // value Ignition actually selects; no renderer behavior currently
    // branches on it, documented honestly, not silently unified).
    bool changed = (buffer != g_g81RenderBufferLastValue);
    if (buffer == 0) g_g81RenderBufferFrontbufferSeen = true;
    if (changed) {
        IGN_LOG("[G81-RENDERBUFFER-STATE]", "caller_guest_eip=0x%08x previous_buffer=0x%x new_buffer=0x%x(%s) "
                                            "frontbuffer_ever_seen=%s",
                callerEip, g_g81RenderBufferLastValue, buffer, bufferName, g_g81RenderBufferFrontbufferSeen ? "YES" : "NO");
        g_g81RenderBufferLastValue = buffer;
    }
    g98_log_state_change("grRenderBuffer", callerEip, g_glideContext.render_buffer, buffer);
    g_glideContext.render_buffer = buffer;
    return 0;   // void function: EAX is don't-care.
}

