// call site is 0x004586f9 (`PUSH 0`) / 0x004586fb (`CALL 0x468c46`);
// 0x468c46 is a standard MSVC IAT jump-thunk (`JMP DWORD PTR [0x46a1f8]`),
// and 0x0046a1f8 is glide2x.dll's IAT slot #17, whose import-table name is
// `_grDepthMask@4` -- an exact match. No EAX test follows the call (next
// instruction at 0x458700 is `PUSH 7` for the following call -- and
// 0x458700 is exactly the caller_guest_eip G6's SEVENTH_GLIDE_CALL log
// reported), confirming a void return. FxBool follows Glide's standard,
// stable public convention (FXFALSE=0, FXTRUE=1 -- unchanged across every
// Glide reference; same "no local header vendored this session" caveat as
// G5/G6's enums), so arg0=0 decodes to FXFALSE: depth writes disabled.
uint32_t grDepthMask_impl(Cpu& c) {
    G148_STATE_TIMER();   // iteration-G148
    uint32_t esp = 0;
    uint32_t callerEip = read_caller_eip(c, esp);
    uint32_t enable = c.arg(0);
    G138_STATE((enable != 0) == (g_glideContext.depth_mask != 0));

    IGN_LOG("[GLIDE-G7]", "grDepthMask(enable=0x%x) caller_guest_eip=0x%08x guest_esp=0x%08x", enable, callerEip, esp);
    IGN_LOG("[GLIDE-G7]", "stack_check: entry_esp=0x%08x argc_dwords=1 expected_esp_after_return=0x%08x (entry_esp+8) return_target=0x%08x",
            esp, esp + 8, callerEip);

    // FxBool is conventionally just 0/1 (FXFALSE/FXTRUE) -- unlike the
    // multi-value enums in G5/G6, any nonzero value is a valid "true" per
    // that convention, so this isn't validated against a fixed set the
    // way GrBuffer_t/GrDepthBufferMode_t were; only the two named,
    // observed values get a name, anything else logs the raw number
    // (still not a guess -- FxBool has no other legal states to be wrong
    // about).
    const char* enableName = (enable == 0) ? "FXFALSE" : (enable == 1) ? "FXTRUE" : nullptr;
    if (enableName) {
        IGN_LOG("[GLIDE-G7]", "grDepthMask(enable=%u -> %s)", enable, enableName);
    } else {
        IGN_LOG("[GLIDE-G7]", "grDepthMask(enable=%u -- nonzero, treated as FXTRUE per FxBool convention)", enable);
    }

    // Part D/O/P: logical state only -- no glDepthMask() call here yet.
    IGN_LOG("[GLIDE-G7]", "previous_depth_mask=0x%x", g_glideContext.depth_mask);
    g98_log_state_change("grDepthMask", callerEip, g_glideContext.depth_mask, enable);
    g_glideContext.depth_mask = enable;
    G148_NOTE(ign::g148::kFamDepthMask, enable != 0 ? 1u : 0u);   // iteration-G148: the packet (one compare, one bit)
    IGN_LOG("[GLIDE-G7]", "depth_mask=%s", enableName ? enableName : (enable ? "FXTRUE" : "FXFALSE"));
    return 0;   // void function: EAX is don't-care.
}

