uint32_t grBufferClear_impl(Cpu& c) {
    uint32_t esp = 0;
    uint32_t callerEip = read_caller_eip(c, esp);
    uint32_t color = c.arg(0);
    uint32_t alpha = c.arg(1);
    uint32_t depth = c.arg(2);
    static uint32_t g98LastClearColor=0xffffffffu,g98LastClearAlpha=0xffffffffu,g98LastClearDepth=0xffffffffu;
    g98_timeline("CLEAR",callerEip);
    g98_log_state_change("grBufferClear.color",callerEip,g98LastClearColor,color);
    g98_log_state_change("grBufferClear.alpha",callerEip,g98LastClearAlpha,alpha);
    g98_log_state_change("grBufferClear.depth",callerEip,g98LastClearDepth,depth);
    g98LastClearColor=color;g98LastClearAlpha=alpha;g98LastClearDepth=depth;
#ifdef IGNITION_RENDERER_3DFX
    g93_record(G93_EV_CLEAR, callerEip);   // iteration-G93, Parte 7
#endif
#ifdef G104_FRAME_AWARE_LFB_COMPOSITOR
    g113_on_buffer_clear(c, color);   // iteration-G113: overlay-layer clear (race/results scenes, before the first LFB lock only)
#endif
    if (g_g125.langNode) { g126_mirror_clear(c, color); }   // iteration-G126: language-selection node only -- the clear also erases what the LFB held, like on the real framebuffer

    // iteration-G14, Parte C: unchanged behavior, reduced log volume once
    // the loop is clearly repeating -- cycle index is read from
    // g_completedSwapCount (grBufferSwap_impl's own counter), since a
    // clear/swap pair share one cycle and this fires before that cycle's
    // swap increments it.
#ifdef IGNITION_RENDERER_3DFX
    bool verbose = (g_completedSwapCount < kDetailedLogCycles);
#else
    bool verbose = true;
#endif

    if (verbose) {
        IGN_LOG("[GLIDE-G10]", "grBufferClear(color=0x%08x, alpha=0x%02x, depth=0x%04x) caller_guest_eip=0x%08x guest_esp=0x%08x runtime_call_index=%u",
                color, alpha, depth, callerEip, esp, g_glideRuntimeCallIndex);
        IGN_LOG("[GLIDE-G10]", "stack_check: entry_esp=0x%08x argc_dwords=3 expected_esp_after_return=0x%08x (entry_esp+16) return_target=0x%08x",
                esp, esp + 16, callerEip);
    }

    float r = ((color >> 16) & 0xFF) / 255.0f;
    float g = ((color >> 8) & 0xFF) / 255.0f;
    float b = (color & 0xFF) / 255.0f;
    float a = (alpha & 0xFF) / 255.0f;   // grBufferClear's explicit alpha param, not color's own top byte
    if (verbose) {
        IGN_LOG("[GLIDE-G10]", "decoded_clear_color: r=%.3f g=%.3f b=%.3f a=%.3f", r, g, b, a);
        IGN_LOG("[GLIDE-G10]", "depth_clear_requested=0x%04x", depth);
    }

    // Parte F/G: depth_buffer_mode/num_aux_buffers are read from
    // GlideContext, not hardcoded, so this reasoning still applies
    // correctly if a later iteration changes either -- but current state
    // (G6/G4E) is DISABLE/0, so no depth clear is performed this
    // iteration regardless of the depth arg Glide always passes.
    bool depthBufferActive = (g_glideContext.depth_buffer_mode != 0) && (g_glideContext.num_aux_buffers > 0);
    if (verbose) IGN_LOG("[GLIDE-G10]", "depth_buffer_active=%s", depthBufferActive ? "YES" : "NO");

#ifdef IGNITION_RENDERER_3DFX
    GLbitfield clearMask = GL_COLOR_BUFFER_BIT;
    if (depthBufferActive) clearMask |= GL_DEPTH_BUFFER_BIT;
    if (verbose) IGN_LOG("[GLIDE-G10]", "clear_mask=%s", depthBufferActive ? "GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT" : "GL_COLOR_BUFFER_BIT");

    // iteration-G84, Parte 10/13: pre-clear GL state, captured only for the
    // first 8 real-race clears (matches [G83-RACE-CLEAR-DETAIL]'s own cap,
    // so this costs nothing on the other ~520 non-race clears G82's own
    // hardware run already measured). This is the CURRENT GL render
    // target's own state -- distinct from, and not necessarily the same
    // physical buffer as, the scanout base sampled below (see
    // [G84-CLEAR-TARGET]'s own note on why that identity isn't
    // recoverable).
    bool g84WantClearProbe = g_g76RealRaceStarted && g_g82ClearRaceCalls < 8;
    GLint g84ClearVp[4] = {0, 0, 0, 0};
    uint32_t g84PreClearGlHash = 0;
    if (g84WantClearProbe) {
        glGetIntegerv(GL_VIEWPORT, g84ClearVp);
        g84PreClearGlHash = g80_hash_roi(g84ClearVp);
    }

    // Parte I/M: no vglSwapBuffers here -- grBufferClear is not
    // presentation. The guest itself must reach grBufferSwap. Always
    // executed regardless of log verbosity -- G14 only reduces LOGGING,
    // never behavior (Part U: grBufferClear/grBufferSwap/grClipWindow
    // stay frozen).
    g100_before_clear(callerEip);
    glClearColor(r, g, b, a);
    glClear(clearMask);
    g100_after_clear(callerEip);

    uint32_t g84PostClearGlHash = 0;
    uint32_t g84PostClearTiles[kG82GridTiles];
    if (g84WantClearProbe) {
        g84PostClearGlHash = g80_hash_roi(g84ClearVp);
        g84_capture_gl_tilemap(g84ClearVp, g84PostClearTiles);
    }

    // iteration-G82, Parte 8: full clear-lifetime audit -- total calls,
    // last caller/timestamp, updated every call (RAM only, printed once
    // by grBufferSwap_impl's own G82 milestone hook).
    ++g_g82ClearTotalCalls;
    g_g82ClearLastEip = callerEip;
    g_g82ClearLastMs = wx86_now_ms();
    if (g_g76RealRaceStarted) {
        ++g_g82ClearRaceCalls;
        // iteration-G83, Parte 19/20: per-race-clear detail + buffer
        // correlation -- capped at 8 (G82's own measured 4 was already
        // small; a little headroom costs nothing).
        if (g_g82ClearRaceCalls <= 8) {
            IGN_LOG("[G83-RACE-CLEAR-DETAIL]", "race_clear#%u caller_guest_eip=0x%08x swap_index=%d color=0x%08x alpha=0x%02x depth=0x%04x "
                                               "host_glClearColor=(%.3f,%.3f,%.3f,%.3f) host_glClear_mask=%s",
                    g_g82ClearRaceCalls, callerEip, g_completedSwapCount, color, alpha, depth,
                    r, g, b, a, depthBufferActive ? "COLOR|DEPTH" : "COLOR");
            SceDisplayFrameBuf g83ClearFb;
            if (g81_get_scanout(g83ClearFb)) {
                IGN_LOG("[G83-CLEAR-BUFFER-CORRELATION]", "race_clear#%u scanout_base_at_clear_time=%p roi_hash_at_clear_time=0x%08x",
                        g_g82ClearRaceCalls, g83ClearFb.base, g81_hash_scanout_roi(g83ClearFb));
                // iteration-G84, Parte 13: G83 only ever correlated a clear
                // with the CURRENT SCANOUT (front/displayed) buffer -- that
                // is NOT necessarily the buffer this glClear() just wrote
                // to (the GL render target is a separate, internally-
                // rotated vitaGL concept with no public API exposing which
                // physical address it maps to). Report both explicitly
                // instead of conflating them.
                IGN_LOG("[G84-CLEAR-TARGET]", "race_clear#%u scanout_base_at_clear_time=%p "
                                              "gl_render_target_identity_recoverable=NO (vitaGL exposes no public "
                                              "API mapping the current GL render target to a physical scanout "
                                              "buffer address) pre_clear_gl_hash=0x%08x post_clear_gl_hash=0x%08x "
                                              "clear_visible_on_gl_render_target=%s",
                        g_g82ClearRaceCalls, g83ClearFb.base, g84PreClearGlHash, g84PostClearGlHash,
                        (g84PostClearGlHash != g84PreClearGlHash) ? "YES" : "UNCHANGED_OR_SAME_COLOR");
            }
            // iteration-G84, Parte 10: does the CURRENT GL render target
            // (not the scanout) go back to matching the loading reference
            // right after this clear? Expected near 0%% if the clear is
            // reaching whatever buffer later gets presented; if it stays
            // high, either the clear is landing on the wrong buffer or the
            // loading content is being redrawn again afterward.
            if (g_g82LoadingTilesValid) {
                int same = 0;
                for (int t = 0; t < kG82GridTiles; ++t) if (g84PostClearTiles[t] == g_g82LoadingTiles[t]) ++same;
                double stalePct = 100.0 * (double)same / (double)kG82GridTiles;
                IGN_LOG("[G84-POST-CLEAR-STATE]", "race_clear#%u total_tiles=%d stale_tiles_vs_loading=%d changed_tiles=%d stale_percent=%.1f",
                        g_g82ClearRaceCalls, kG82GridTiles, same, kG82GridTiles - same, stalePct);
            }
        }
    }

    // iteration-G81, Parte 20/21: RAM-only race-clear audit -- confirms,
    // from real runtime data, whether grBufferClear is even CALLED during
    // real-race frames and with what color, before the first 20 such
    // calls are summarized once. The glClearColor/glClear pair above is
    // UNCONDITIONAL (not gated by `verbose`) -- this only checks whether
    // the GUEST itself keeps calling grBufferClear during real race.
    if (g_g76RealRaceStarted && g_g81RaceClearCount < 20) {
        ++g_g81RaceClearCount;
        if (g_g81RaceClearCount <= 8) {
            g_g81RaceClearColors[g_g81RaceClearCount - 1] = color;
        }
        if (g_g81RaceClearCount == 20) {
            char colorList[8 * 12 + 1] = {0};
            size_t rcPos = 0;
            for (int i = 0; i < 8; ++i) {
                int n = snprintf(colorList + rcPos, sizeof(colorList) - rcPos, "0x%06x ", g_g81RaceClearColors[i] & 0xFFFFFFu);
                if (n > 0) rcPos += (size_t)n;
            }
            IGN_LOG("[G81-RACE-CLEAR]", "clear_calls_in_first_20=%u host_glClearColor_called=YES host_glClear_COLOR_BUFFER_BIT_called=YES "
                                        "first_8_clear_colors: %s", g_g81RaceClearCount, colorList);
        }
    }

    GLenum glErr = glGetError();
    if (verbose) {
        IGN_LOG("[GLIDE-G10]", "vitaGL clear executed");
        IGN_LOG("[GLIDE-G10]", "glGetError_after_clear=0x%04x", (unsigned)glErr);
    } else if (glErr != 0) {
        // Errors are never suppressed, even past the verbose window.
        IGN_LOG("[GLIDE-G14]", "glGetError_after_clear=0x%04x (non-zero, past verbose window -- reported anyway)", (unsigned)glErr);
    }

    if (!g_firstRealFramebufferOpLogged) {
        g_firstRealFramebufferOpLogged = true;
        IGN_LOG("[GLIDE-G10]", "FIRST_REAL_FRAMEBUFFER_OPERATION (not FIRST_FRAME -- a color clear is not guest-rendered content)");
    }
#else
    // Stable DDraw build: this function is registered defensively (same
    // as every other Glide shim in this file) but Ign_d3d.exe has no
    // glide2x.dll import to ever actually call it -- no vitaGL/GL symbols
    // exist to call in this build, so nothing further happens here.
    IGN_LOG("[GLIDE-G10]", "clear_mask=%s (DDraw build -- not applied, vitaGL unavailable)", depthBufferActive ? "GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT" : "GL_COLOR_BUFFER_BIT");
#endif

    return 0;   // void function: EAX is don't-care.
}

#ifdef IGNITION_RENDERER_3DFX
// iteration-G14, Parte I: plain diagnostic wraparound sum over the 256
// palette entries -- same formula grTexDownloadTable_impl already uses to
// compute its own checksum, factored out here so the frame-loop watchdog
// can call it too without duplicating the loop. Never writes
// g_glideContext.palette -- read-only.
uint32_t compute_palette_checksum() {
    uint32_t sum = 0;
    for (uint32_t i = 0; i < 256; ++i) sum += g_glideContext.palette[i];
    return sum;
}

// iteration-G14, Parte I: called only at safe points (every
// kSummaryLogInterval cycles, and once more when the watchdog trips) --
// never on every instruction/frame. Logs a change, never modifies
// anything.
void log_g14_watch_palette_checksum(const char* when) {
    if (!g_glideContext.palette_valid) return;
    uint32_t checksum = compute_palette_checksum();
    if (!g_paletteChecksumCaptured) {
        g_paletteChecksumCaptured = true;
        g_paletteChecksumInitial = checksum;
        g_lastPaletteChecksum = checksum;
        IGN_LOG("[GLIDE-G14]", "palette_checksum_captured (%s): 0x%08x", when, checksum);
        return;
    }
    if (checksum != g_lastPaletteChecksum) {
        IGN_LOG("[GLIDE-G14]", "palette_memory_changed (%s) old_checksum=0x%08x new_checksum=0x%08x",
                when, g_lastPaletteChecksum, checksum);
        g_lastPaletteChecksum = checksum;
    }
}

// iteration-G14, Parte E: one-shot summary of everything Part D/E asked
// to count -- called from the frame-loop watchdog (either cap) and from
// the "next unimplemented Glide call found" trap, so both G14 exit paths
// (RESULTADO IDEAL A and B) report the same counters.
void log_g14_activity_summary(const char* reason) {
    IGN_LOG("[GLIDE-G15]", "activity_summary (%s):", reason);
    IGN_LOG("[GLIDE-G15]", "  frame_cycles=%d", g_completedSwapCount);
    IGN_LOG("[GLIDE-G15]", "  kernel32_call_count(total)=%u (createfilea=%u readfile=%u)", g_ign_kernel32_call_count, g_ign_createfilea_count, g_ign_readfile_count);
    IGN_LOG("[GLIDE-G15]", "  user32_call_count(total)=%u (peek=%u get=%u dispatch=%u post=%u)",
            g_ign_user32_call_count, g_ign_peekmessage_count, g_ign_getmessage_count, g_ign_dispatchmessage_count, g_ign_postmessage_count);
    IGN_LOG("[GLIDE-G15]", "  winmm_call_count(total)=%u (timeGetTime=%u timeSetEvent=%u timeKillEvent=%u joyGetPosEx=%u)",
            g_ign_winmm_call_count, g_ign_timegettime_count, g_ign_timesetevent_count, g_ign_timekillevent_count, g_ign_joygetposex_count);
    IGN_LOG("[GLIDE-G15]", "  dinput_call_count(total)=%u (implemented methods + unimplemented traps alike; a real unimplemented call halts separately via its own [DINPUT] log line before this summary could even run)", g_ign_dinput_call_count);
    IGN_LOG("[GLIDE-G15]", "  glide_runtime_call_index=%u", g_glideRuntimeCallIndex);
    IGN_LOG("[GLIDE-G15]", "  palette_checksum_initial=0x%08x", g_paletteChecksumInitial);
    IGN_LOG("[GLIDE-G15]", "  palette_checksum_final=0x%08x", g_lastPaletteChecksum);
}
#endif

// grBufferSwap(FxU32 swap_interval) -> void. 1 dword arg, decorated
// _grBufferSwap@4 -- confirmed against Ignition's own real call this
// iteration (G10's hardware log gave ELEVENTH_GLIDE_CALL=grBufferSwap,
// caller_guest_eip=0x00458738, arg0=0x0/swap_interval). Confirmed by
// direct disassembly + import-table cross-reference (same methodology as
// G5-G10, not guessed): call site is 0x458731 (`PUSH 0x0`) / 0x458733
// (`CALL 0x449e46`); 0x449e46 is the same MSVC IAT jump-thunk cluster as
// grBufferClear's (`JMP DWORD PTR [0x46a228]`), and 0x0046a228 is
// glide2x.dll's IAT slot #29 (same reparsed Import Name Table as G10),
// whose import-table name is `_grBufferSwap@4` -- an exact match. No EAX
// test follows the call (next instruction at 0x458738 is `PUSH 0xffff`
// for a REPEATED grBufferClear -- and 0x458738 is exactly the
// caller_guest_eip G10's ELEVENTH_GLIDE_CALL log reported), confirming a
// void return.
//
// Parte B: swap_interval's semantics per Glide 2.x's standard, stable
// public convention (well-established public API knowledge -- same "no
// local header vendored this session" caveat as every enum decoded since
// G5): 0 = swap immediately, do not wait for a vertical retrace; 1 = wait
// for exactly one vertical retrace (standard vsync); N>1 = wait for N
// vertical retraces (a frame-rate limiter, e.g. 2 halves the effective
// frame rate). Ignition passes 0 this call -- logged for the record, but
// per Part K, NO pacing/vblank-wait logic is added this iteration.
//
// Parte D: vglSwapBuffers(GLboolean has_commondialog) is vitaGL's public
// present call (checked vitaGL.h this iteration: exactly one GLboolean
// parameter, controlling Common Dialog support during the swap --
// UNRELATED to Glide's swap_interval; there is no vitaGL parameter that
// swap_interval maps onto, so it is NOT passed through in any form).
// GL_FALSE is used, same value as the G4C/G4B selftest's
// already-hardware-proven call, since this build never uses Common
// Dialog.
#ifdef IGNITION_RENDERER_3DFX
// iteration-G19, Parte L/O: forward-declared here so grBufferSwap_impl
// (below) can call it -- defined further down, after
// glide_logical_rect_to_physical_scissor (which it reuses), right next
// to grLfbUnlock_impl which is the only place lfb_dirty gets set.
void lfb_blit_to_backbuffer();
// iteration-G36, Parte H/I: the deferred upload -- see grLfbUnlock_impl's
// own comment for the full safety argument. Defined right next to
// lfb_blit_to_backbuffer(), called from grBufferSwap_impl immediately
// before it, at most once per present.
void lfb_upload_texture(Cpu& c);
// iteration-G104: the new batched sparse-overlay presenter -- forward-
// declared here (same pattern as the two functions above) so
// grBufferSwap_impl can call it; defined right next to lfb_blit_to_
// backbuffer() since it reuses the same texture/state-save-restore style
// and glide_logical_xy_to_physical (defined between here and there).
void g104_sparse_overlay_blit();
// iteration-G142: cheap per-frame accumulators + transition lines of the HUD overlay (defined with the compositor; see win32/g142_visual.h)
void g142_swap_begin(Cpu& c);
void g142_classify_note(bool armedScene, bool hasGL, bool cleanLayer, bool validGeom, uint32_t rejectMask, uint32_t cls);
void g142_frame_end(Cpu& c);
void g142_overlay_note(bool wasBlend, bool wasDepth, bool wasCull, uint32_t prevTex, const GLint* vp);
void g142_after_overlay(const GLint* vp);
void g142_pause_edge(bool paused);
void g142_race_window_suffix(char* out, size_t n);
// iteration-G143: region lifetime (defined after the G142 block; see win32/g143_regions.h)
void g143_note_lock(Cpu& c, uint32_t esp, uint32_t caller, uint32_t mode, uint32_t origin, uint32_t pixelPipeline);
void g143_swap_begin(Cpu& c);
void g143_new_race();
void g143_frame_writers_reset();
void g143_swap_end(Cpu& c, bool normalClearDone);
void g143_context_reset();
bool g143_key_pinned();
// iteration-G144: incremental compositor fast path (defined next to g115_overlay_upload / after the G143 block)
void g144_overlay_upload();
void g144_mode_info(bool& race, uint32_t& framesInMode, bool& guardPending, bool& transition);
void g144_frame_close();
void g144_context_reset();
void g145_context_reset();   // iteration-G145 (defined with the lifecycle code next to g138_frame_tick): a new Glide context drops the scissor knowledge and the lifecycle state
unsigned int g144_overlay_texture();
bool g144_ring_ready();
#endif

#ifdef IGNITION_RENDERER_3DFX
// iteration-G80, Parte 17/20-22: 8 fixed sample points (never a full
// framebuffer read) covering center/corners/HUD-area/world-area, plus a
// tiny 64x64 ROI additive hash around center -- called twice (pre/post
// the LFB blit) from the SAME single diagnostic frame, so the two calls'
// output is directly comparable point-for-point.
struct G80FbSample { int x, y; const char* name; uint8_t rgb[3]; };
void g80_sample_fb_points(G80FbSample* pts, int count, const GLint* vp) {
#ifdef G103_ZERO_DIRTY_LFB_GUARD
    (void)pts; (void)count; (void)vp;
#else
    for (int i = 0; i < count; ++i) {
        int px = vp[0] + pts[i].x;
        int py = vp[1] + pts[i].y;
        pts[i].rgb[0] = pts[i].rgb[1] = pts[i].rgb[2] = 0;
        glReadPixels(px, py, 1, 1, GL_RGB, GL_UNSIGNED_BYTE, pts[i].rgb);
    }
#endif
}
uint32_t g80_hash_roi(const GLint* vp) {
#ifdef G103_ZERO_DIRTY_LFB_GUARD
    (void)vp;
    return 0;
#else
    int cx = vp[0] + vp[2] / 2, cy = vp[1] + vp[3] / 2;
    int half = 32;   // 64x64 total
    std::vector<uint8_t> buf((size_t)64 * 64 * 3);
    glReadPixels(cx - half, cy - half, 64, 64, GL_RGB, GL_UNSIGNED_BYTE, buf.data());
    uint32_t h = 2166136261u;   // FNV-1a, diagnostic use only
    for (uint8_t b : buf) { h ^= b; h *= 16777619u; }
    return h;
#endif
}

// iteration-G81, Parte 8-12: read-only physical-display-scanout sampling,
// the SAME 8 fixed points G80's own GL probe already uses (so the two are
// directly comparable point-for-point) plus a 64x64 center ROI hash, read
// straight from sceDisplayGetFrameBuf's own `base` pointer (real Vita SDK
// API, confirmed present -- never sceDisplaySetFrameBuf, display mode is
// never touched). Pixel format is ALWAYS SCE_DISPLAY_PIXELFORMAT_A8B8G8R8
// per the real SDK header (the only value the enum defines) -- byte order
// in memory is the well-established Vita homebrew convention (R,G,B,A at
// increasing addresses, matching vitaGL's own default render-target
// layout), not guessed per-project.
bool g81_get_scanout(SceDisplayFrameBuf& fb) {
    fb.size = sizeof(fb);
    return sceDisplayGetFrameBuf(&fb, SCE_DISPLAY_SETBUF_IMMEDIATE) == 0 && fb.base != nullptr;
}
void g81_sample_scanout_points(const SceDisplayFrameBuf& fb, G80FbSample* pts, int count) {
    const uint8_t* base = (const uint8_t*)fb.base;
    for (int i = 0; i < count; ++i) {
        uint32_t px = (uint32_t)pts[i].x, py = (uint32_t)pts[i].y;
        if (px >= fb.width || py >= fb.height) { pts[i].rgb[0] = pts[i].rgb[1] = pts[i].rgb[2] = 0; continue; }
        const uint8_t* p = base + ((size_t)py * fb.pitch + px) * 4u;
        pts[i].rgb[0] = p[0]; pts[i].rgb[1] = p[1]; pts[i].rgb[2] = p[2];   // R,G,B (A ignored)
    }
}
uint32_t g81_hash_scanout_roi(const SceDisplayFrameBuf& fb) {
    uint32_t cx = fb.width / 2, cy = fb.height / 2;
    uint32_t half = 32;
    const uint8_t* base = (const uint8_t*)fb.base;
    uint32_t h = 2166136261u;
    for (uint32_t row = 0; row < 64; ++row) {
        uint32_t py = cy - half + row;
        if (py >= fb.height) continue;
        const uint8_t* rowPtr = base + (size_t)py * fb.pitch * 4u;
        for (uint32_t col = 0; col < 64; ++col) {
            uint32_t px = cx - half + col;
            if (px >= fb.width) continue;
            const uint8_t* p = rowPtr + (size_t)px * 4u;
            h ^= p[0]; h *= 16777619u; h ^= p[1]; h *= 16777619u; h ^= p[2]; h *= 16777619u;
        }
    }
    return h;
}

// iteration-G82, Parte 11: fill a kG82GridTiles-sized array with one
// lightweight hash per tile, sampling a small 4x4 block near each tile's
// center (16 reads/tile, 96 tiles = 1536 reads total per capture --
// trivial, never a full-screen dump).
void g82_capture_tilemap(const SceDisplayFrameBuf& fb, uint32_t* out) {
    if (!fb.base || !fb.width || !fb.height) { for (int i = 0; i < kG82GridTiles; ++i) out[i] = 0; return; }
    const uint8_t* base = (const uint8_t*)fb.base;
    for (int ty = 0; ty < kG82GridRows; ++ty) {
        for (int tx = 0; tx < kG82GridCols; ++tx) {
            uint32_t cx = (fb.width * (uint32_t)tx * 2 + fb.width) / (uint32_t)(kG82GridCols * 2);
            uint32_t cy = (fb.height * (uint32_t)ty * 2 + fb.height) / (uint32_t)(kG82GridRows * 2);
            uint32_t h = 2166136261u;
            for (int dy = -2; dy < 2; ++dy) {
                uint32_t py = (uint32_t)((int)cy + dy);
                if (py >= fb.height) continue;
                const uint8_t* row = base + (size_t)py * fb.pitch * 4u;
                for (int dx = -2; dx < 2; ++dx) {
                    uint32_t px = (uint32_t)((int)cx + dx);
                    if (px >= fb.width) continue;
                    const uint8_t* p = row + (size_t)px * 4u;
                    h ^= p[0]; h *= 16777619u; h ^= p[1]; h *= 16777619u; h ^= p[2]; h *= 16777619u;
                }
            }
            out[ty * kG82GridCols + tx] = h;
        }
    }
}

// iteration-G82, Parte 12-14: diff a captured tilemap against the frozen
// loading tilemap, classify, print counts + ONE ASCII grid.
void g82_diff_and_log_tilemap(const char* stateName, const uint32_t* tiles) {
    if (!g_g82LoadingTilesValid) {
        IGN_LOG("[G82-PARTIAL-REDRAW]", "state=%s SKIPPED(no_loading_tilemap_captured_yet)", stateName);
        return;
    }
    int identical = 0, changed = 0;
    char grid[kG82GridRows * (kG82GridCols + 1) + 1] = {0};
    int gp = 0;
    for (int ty = 0; ty < kG82GridRows; ++ty) {
        for (int tx = 0; tx < kG82GridCols; ++tx) {
            int i = ty * kG82GridCols + tx;
            bool same = (tiles[i] == g_g82LoadingTiles[i]);
            if (same) ++identical; else ++changed;
            grid[gp++] = same ? '.' : 'X';
        }
        grid[gp++] = '\n';
    }
    double stalePct = 100.0 * (double)identical / (double)kG82GridTiles;
    IGN_LOG("[G82-SCANOUT-TILEMAP]", "state=%s grid=%dx%d captured=YES", stateName, kG82GridCols, kG82GridRows);
    IGN_LOG("[G82-PARTIAL-REDRAW]", "state=%s total_tiles=%d still_loading_identical=%d changed=%d stale_background_percent=%.1f",
            stateName, kG82GridTiles, identical, changed, stalePct);
    // Part 14: ONE grid only -- gated to the single most representative
    // state (RACE_10, past initial transient, before extended runtime).
    if (strcmp(stateName, "RACE_10") == 0) {
        IGN_LOG("[G82-TILE-DIFF-GRID]", "state=%s (.=identical_to_loading X=changed)\n%s", stateName, grid);
    }
}

// iteration-G84, Parte 9-11: GL-side counterpart to g82_capture_tilemap --
// same kG82GridCols x kG82GridRows tile layout, same tile-center math, but
// sampled from the CURRENT GL render target via glReadPixels (one 4x4-pixel
// block per tile, 96 tiny reads, never a full-screen dump) instead of a raw
// sceDisplayGetFrameBuf pointer. This is needed anywhere the physical
// scanout has not caught up yet (e.g. mid-frame, right after a clear, or
// immediately after vglSwapBuffers but before the next present) -- exactly
// the cases G84's own required tags ([G84-NEW-BACKBUFFER-STATE],
// [G84-POST-CLEAR-STATE], [G84-AFTER-10-TRIS], [G84-AFTER-100-TRIS]) need.
//
// Coordinate-space note: this project's own G80/G81 code (g81_capture_
// milestone, [G81-PRESENT-COMPARE]) has always compared GL-viewport pixel
// coordinates directly against physical-scanout pixel coordinates with only
// a width/height ratio rescale, no vertical flip -- and used "same=YES/NO"
// from that direct comparison as real diagnostic signal across G80-G83.
// This function follows that SAME established (if never explicitly named)
// no-flip convention for consistency, rather than introducing a new,
// untested assumption for G84 alone.
void g84_capture_gl_tilemap(const GLint* vp, uint32_t* out) {
#ifdef G103_ZERO_DIRTY_LFB_GUARD
    (void)vp;
    memset(out, 0, sizeof(uint32_t) * kG82GridTiles);
#else
    int w = vp[2], h = vp[3];
    if (w <= 0 || h <= 0) { for (int i = 0; i < kG82GridTiles; ++i) out[i] = 0; return; }
    uint8_t block[4 * 4 * 3];
    for (int ty = 0; ty < kG82GridRows; ++ty) {
        for (int tx = 0; tx < kG82GridCols; ++tx) {
            int cx = vp[0] + (w * tx * 2 + w) / (kG82GridCols * 2);
            int cy = vp[1] + (h * ty * 2 + h) / (kG82GridRows * 2);
            glReadPixels(cx - 2, cy - 2, 4, 4, GL_RGB, GL_UNSIGNED_BYTE, block);
            uint32_t hh = 2166136261u;
            for (uint8_t b : block) { hh ^= b; hh *= 16777619u; }
            out[ty * kG82GridCols + tx] = hh;
        }
    }
#endif
}

// iteration-G81, Parte 6/16: one shared capture routine for BOTH the GL
// backbuffer (Part 12) and the physical scanout (Part 10/11), tagged with
// a caller-supplied milestone name, so [G81-PRESENT-COMPARE]/[G81-FRAME-
// LIFETIME] always compare the SAME state from the SAME call site.
void g81_capture_milestone(const char* stateName, const GLint* vp) {
#ifdef G103_ZERO_DIRTY_LFB_GUARD
    (void)stateName; (void)vp;
    return;
#else
    G80FbSample glPts[8], scanPts[8];
    int w = vp[2], h = vp[3];
    int coords[8][2] = {
        {w/2, h/2}, {w/8, h/8}, {w*7/8, h/8}, {w/8, h*7/8},
        {w*7/8, h*7/8}, {w/2, h/10}, {w/2, h/2 - h/6}, {w/2, h/2 + h/6}
    };
    const char* names[8] = {"center", "upper_left", "upper_right", "lower_left",
                             "lower_right", "hud_top_area", "world_upper_center", "world_lower_center"};
    for (int i = 0; i < 8; ++i) { glPts[i] = {coords[i][0], coords[i][1], names[i], {0,0,0}}; scanPts[i] = glPts[i]; }
    g80_sample_fb_points(glPts, 8, vp);
    uint32_t glHash = g80_hash_roi(vp);
    for (int i = 0; i < 8; ++i) {
        IGN_LOG("[G81-GL-HASH]", "state=%s point=%s rgb=(%u,%u,%u)", stateName, glPts[i].name, glPts[i].rgb[0], glPts[i].rgb[1], glPts[i].rgb[2]);
    }
    IGN_LOG("[G81-GL-HASH]", "state=%s roi_hash=0x%08x", stateName, glHash);

    SceDisplayFrameBuf fb;
    bool haveScanout = g81_get_scanout(fb);
    uint32_t scanHash = 0;
    if (haveScanout) {
        // Parte 8: one-shot, required tag -- exact real SDK fields, never
        // guessed byte order (SCE_DISPLAY_PIXELFORMAT_A8B8G8R8 is the
        // ONLY value the real SDK enum defines).
        static bool g81DisplayFramebufLogged = false;
        if (!g81DisplayFramebufLogged) {
            g81DisplayFramebufLogged = true;
            IGN_LOG("[G81-DISPLAY-FRAMEBUF]", "base=%p pitch=%u pixelformat=0x%x(%s) width=%u height=%u",
                    fb.base, fb.pitch, fb.pixelformat,
                    (fb.pixelformat == SCE_DISPLAY_PIXELFORMAT_A8B8G8R8) ? "SCE_DISPLAY_PIXELFORMAT_A8B8G8R8" : "UNKNOWN",
                    fb.width, fb.height);
        }
        if (fb.width && fb.height) {   // physical coords, NOT GL viewport coords -- scale
            for (int i = 0; i < 8; ++i) {
                scanPts[i].x = (int)((int64_t)coords[i][0] * (int)fb.width / (w ? w : 1));
                scanPts[i].y = (int)((int64_t)coords[i][1] * (int)fb.height / (h ? h : 1));
            }
        }
        g81_sample_scanout_points(fb, scanPts, 8);
        scanHash = g81_hash_scanout_roi(fb);
        for (int i = 0; i < 8; ++i) {
            IGN_LOG("[G81-SCANOUT-SAMPLE]", "state=%s point=%s rgb=(%u,%u,%u)", stateName, scanPts[i].name, scanPts[i].rgb[0], scanPts[i].rgb[1], scanPts[i].rgb[2]);
        }
        IGN_LOG("[G81-SCANOUT-HASH]", "state=%s roi_hash=0x%08x base=%p pitch=%u format=0x%x width=%u height=%u",
                stateName, scanHash, fb.base, fb.pitch, fb.pixelformat, fb.width, fb.height);
    } else {
        IGN_LOG("[G81-SCANOUT-HASH]", "state=%s sceDisplayGetFrameBuf_FAILED", stateName);
    }

    IGN_LOG("[G81-PRESENT-COMPARE]", "state=%s gl_hash=0x%08x scanout_hash=0x%08x same=%s",
            stateName, glHash, scanHash, (haveScanout && glHash == scanHash) ? "YES" : "NO");

    bool hudChanged = (glPts[5].rgb[0] != scanPts[5].rgb[0] || glPts[5].rgb[1] != scanPts[5].rgb[1] || glPts[5].rgb[2] != scanPts[5].rgb[2]);
    IGN_LOG("[G81-HUD-WORLD-SPLIT]", "state=%s hud_top_area_gl=(%u,%u,%u) hud_top_area_scanout=(%u,%u,%u) "
                                     "world_upper_gl=(%u,%u,%u) world_upper_scanout=(%u,%u,%u) hud_vs_scanout_differ=%s",
            stateName, glPts[5].rgb[0], glPts[5].rgb[1], glPts[5].rgb[2],
            scanPts[5].rgb[0], scanPts[5].rgb[1], scanPts[5].rgb[2],
            glPts[6].rgb[0], glPts[6].rgb[1], glPts[6].rgb[2],
            scanPts[6].rgb[0], scanPts[6].rgb[1], scanPts[6].rgb[2],
            hudChanged ? "YES" : "NO");
 #endif
}
#endif

