void g101_roi_capture(G101RoiTrace&tr,const char*name,bool compare){if(tr.eventCount>=kG101MaxRoiEvents||tr.maxX<tr.minX||tr.maxY<tr.minY)return;glGetIntegerv(GL_VIEWPORT,tr.viewport);tr.scissorEnabled=glIsEnabled(GL_SCISSOR_TEST);if(tr.scissorEnabled)glGetIntegerv(GL_SCISSOR_BOX,tr.scissor);else memcpy(tr.scissor,tr.viewport,sizeof(tr.viewport));int left=std::max(tr.viewport[0],tr.scissor[0]),bottom=std::max(tr.viewport[1],tr.scissor[1]),right=std::min(tr.viewport[0]+tr.viewport[2],tr.scissor[0]+tr.scissor[2]),top=std::min(tr.viewport[1]+tr.viewport[3],tr.scissor[1]+tr.scissor[3]);int x=std::max(left,(int)floorf(tr.minX)),y=std::max(bottom,(int)floorf(tr.minY));int x2=std::min(right,(int)ceilf(tr.maxX)),y2=std::min(top,(int)ceilf(tr.maxY));if(x2<=x||y2<=y)return;int w=x2-x,h=y2-y;std::vector<uint8_t> pixels((size_t)w*h*4);uint64_t t=wx86_now_us();glFinish();tr.syncUs+=wx86_now_us()-t;++tr.syncs;t=wx86_now_us();glReadPixels(x,y,w,h,GL_RGBA,GL_UNSIGNED_BYTE,pixels.data());tr.readUs+=wx86_now_us()-t;++tr.reads;G101RoiEvent&e=tr.events[tr.eventCount++];e.name=name;e.swap=g_completedSwapCount;e.x=x;e.y=y;e.w=w;e.h=h;e.rawMinX=tr.minX;e.rawMinY=tr.minY;e.rawMaxX=tr.maxX;e.rawMaxY=tr.maxY;e.crc=g101_crc32(pixels.data(),pixels.size());if(compare&&tr.previousX==x&&tr.previousY==y&&tr.previousW==w&&tr.previousH==h&&tr.previous.size()==pixels.size()){e.preCrc=g101_crc32(tr.previous.data(),tr.previous.size());for(int py=0;py<h;++py)for(int px=0;px<w;++px){size_t o=((size_t)py*w+px)*4;if(memcmp(&tr.previous[o],&pixels[o],4)){uint32_t before=0,after=0;memcpy(&before,&tr.previous[o],4);memcpy(&after,&pixels[o],4);if(!e.changed){e.firstX=x+px;e.firstY=y+py;e.firstBefore=before;e.firstAfter=after;e.minX=e.maxX=x+px;e.minY=e.maxY=y+py;}e.lastX=x+px;e.lastY=y+py;e.lastBefore=before;e.lastAfter=after;e.minX=std::min(e.minX,x+px);e.minY=std::min(e.minY,y+py);e.maxX=std::max(e.maxX,x+px);e.maxY=std::max(e.maxY,y+py);++e.changed;}}}tr.previous.swap(pixels);tr.previousX=x;tr.previousY=y;tr.previousW=w;tr.previousH=h;}
