G102State g102_get_state(){G102State s;glGetIntegerv(GL_FRAMEBUFFER_BINDING,&s.fbo);glGetIntegerv(GL_VIEWPORT,s.viewport);s.scissorEnabled=glIsEnabled(GL_SCISSOR_TEST);glGetIntegerv(GL_SCISSOR_BOX,s.scissor);glGetIntegerv(GL_ACTIVE_TEXTURE,&s.activeTexture);glActiveTexture(GL_TEXTURE0);glGetIntegerv(GL_TEXTURE_BINDING_2D,&s.texture);s.textureEnabled=glIsEnabled(GL_TEXTURE_2D);glGetIntegerv(GL_CURRENT_PROGRAM,&s.program);glGetIntegerv(GL_MATRIX_MODE,&s.matrixMode);glGetTexEnviv(GL_TEXTURE_ENV,GL_TEXTURE_ENV_MODE,&s.texEnv);glGetIntegerv(GL_UNPACK_ROW_LENGTH,&s.unpackRowLength);s.blend=glIsEnabled(GL_BLEND);s.depth=glIsEnabled(GL_DEPTH_TEST);s.cull=glIsEnabled(GL_CULL_FACE);s.vertexArray=glIsEnabled(GL_VERTEX_ARRAY);s.texArray=glIsEnabled(GL_TEXTURE_COORD_ARRAY);glGetBooleanv(GL_DEPTH_WRITEMASK,&s.depthMask);glGetBooleanv(GL_COLOR_WRITEMASK,s.colorMask);glGetFloatv(GL_CURRENT_COLOR,s.currentColor);s.currentColorValid=GL_TRUE;glGetIntegerv(GL_VERTEX_ARRAY_SIZE,&s.vertexSize);glGetIntegerv(GL_VERTEX_ARRAY_TYPE,&s.vertexType);glGetIntegerv(GL_VERTEX_ARRAY_STRIDE,&s.vertexStride);glGetPointerv(GL_VERTEX_ARRAY_POINTER,&s.vertexPtr);glGetIntegerv(GL_TEXTURE_COORD_ARRAY_SIZE,&s.texSize);glGetIntegerv(GL_TEXTURE_COORD_ARRAY_TYPE,&s.texType);glGetIntegerv(GL_TEXTURE_COORD_ARRAY_STRIDE,&s.texStride);glGetPointerv(GL_TEXTURE_COORD_ARRAY_POINTER,&s.texPtr);glActiveTexture((GLenum)s.activeTexture);return s;}
