 if(!g_g92PhaseA.armed||g_g92PhaseA.done)return nullptr;if(g_g92PhaseA.count==kG100GoodFrame)return &g_g100Good;if(g_g92PhaseA.count==kG100FreezeFrame)return &g_g100Freeze;return nullptr;
