void g100_before_lfb(uint32_t caller){G100Trace*tr=g100_active_trace();if(!tr)return;g100_ensure_start(caller);g100_checkpoint("BEFORE_LFB_UPLOAD_BLIT",caller);}
void g100_after_lfb(uint32_t caller){G100Trace*tr=g100_active_trace();if(!tr)return;++tr->blitCount;g100_checkpoint("AFTER_LFB_UPLOAD_BLIT",caller);}
void g100_end_gl_frame(uint32_t caller){G100Trace*tr=g100_active_trace();if(!tr)return;g100_ensure_start(caller);g100_checkpoint("END_GL_BEFORE_SWAP",caller);}
