G100LfbContract* g100_current_contract(){if(!g_g92PhaseA.armed||g_g92PhaseA.done||g_g92PhaseA.count>=kG92FramesPerPhase)return nullptr;int i=g_g92PhaseA.count;if(!((i>=1&&i<=10)||(i>=19&&i<=28)))return nullptr;return &g_g100LfbContracts[i];}
uint32_t g100_lfb_sample_hash(Cpu&c){if(!g_glideContext.lfb_shadow_ptr||!g_glideContext.lfb_stride_bytes)return 0;uint32_t h=2166136261u;for(int y=0;y<8;++y)for(int x=0;x<12;++x){uint16_t v=0;uint32_t px=(uint32_t)((g_glideContext.width*(x*2+1))/24),py=(uint32_t)((g_glideContext.height*(y*2+1))/16);c.read(g_glideContext.lfb_shadow_ptr+py*g_glideContext.lfb_stride_bytes+px*2,&v,2);h^=v&255;h*=16777619u;h^=v>>8;h*=16777619u;}return h;}
