void g100_after_matched_draw(uint32_t caller,GLenum err){G100Trace*tr=g100_active_trace();if(!tr||caller!=kG99MatchedCaller||tr->matchedDraws==0)return;uint32_t ord=tr->matchedDraws;if(ord<=tr->effectCount)tr->effects[ord-1].glError=(uint32_t)err;if(ord==1)g100_checkpoint("AFTER_SELECTED_DRAW_1",caller);else if(ord==4)g100_checkpoint("AFTER_SELECTED_DRAW_4",caller);else if(ord==8)g100_checkpoint("AFTER_SELECTED_DRAW_8",caller);}

