    char de[8192]={0};size_t dp=0;for(uint32_t i=0;i<tr.effectCount;++i){G100DrawEffect&e=tr.effects[i];int n=snprintf(de+dp,sizeof(de)-dp,"d%u{area=%.4g,deg=%u,bbox=%.1f,%.1f-%.1f,%.1f,intersect=%u,scissor=%u,depth=%u/fn=%u/write=%u,blend=%u/%u,%u/eq=0x%x,mask=%u%u%u%u,chroma=%u,tex=%u,mmid=0x%x,dim=%ux%u,texhash=0x%08x,target=%u,err=0x%x};",e.ordinal,e.area,e.degenerate?1:0,e.minX,e.minY,e.maxX,e.maxY,e.intersects?1:0,e.scissor?1:0,e.depth?1:0,e.depthFn,e.depthWrite?1:0,e.blend?1:0,e.blendSrc,e.blendDst,e.blendEq,e.colorMask[0]?1:0,e.colorMask[1]?1:0,e.colorMask[2]?1:0,e.colorMask[3]?1:0,e.chroma?1:0,e.glTexture,e.mmid,e.texW,e.texH,e.texHash,e.renderTarget,e.glError);if(n>0&&dp+(size_t)n<sizeof(de))dp+=(size_t)n;}
    IGN_LOG("[G100-DRAW-EFFECT]","window=%s local_frame=%d verdict=%s geometry_changed_coarse_tiles=%s draws=%s",tr.window,tr.localFrame,verdict,geometryChanged?"YES":"NO",de);
