    const char*last="NONE",*first="NONE",*op="NONE";if(pre&&post&&pre->hash!=0x82ed3ef7u&&post->hash==0x82ed3ef7u){last=pre->type;first=post->type;op="LFB_UPLOAD_PLUS_FULLSCREEN_BLIT";}IGN_LOG("[G100-OVERWRITE-BOUNDARY]","window=%s last_changing_checkpoint=%s first_checkpoint_equal_final_frozen=%s event_between=%s caller=0x%08x",tr.window,last,first,op,post?post->caller:0);
