void g98_hist_add(G98HistogramEntry* h, int& n, uint32_t value, uint32_t gl=0, uint32_t width=0, uint32_t height=0) {
    for (int i=0;i<n;++i) if (h[i].value==value) { ++h[i].count; return; }
    if (n<kG98MaxHistogram) { h[n].value=value; h[n].count=1; h[n].gl=gl; h[n].width=width; h[n].height=height; ++n; }
}
G98StateSnapshot g98_state_snapshot() {
    G98StateSnapshot s; s.color=g_glideContext.color_combine_fnc_raw; s.alpha=g_glideContext.alpha_source_mode;
    s.key=g_glideContext.chromakey_value; s.render=g_glideContext.render_buffer; s.depth=g_glideContext.depth_buffer_mode;
    s.depthMask=g_glideContext.depth_mask; s.depthFn=g_glideContext.depth_function; s.cull=g_glideContext.cull_mode;
    s.clip[0]=g_glideContext.clip_min_x;s.clip[1]=g_glideContext.clip_min_y;s.clip[2]=g_glideContext.clip_max_x;s.clip[3]=g_glideContext.clip_max_y;
    s.mmid=g_glideContext.current_texture_mmid;s.chroma=g_glideContext.chromakey_enabled;s.blend=g_glideContext.alpha_blend_valid;
    s.bs=g_glideContext.alpha_blend_rgb_src;s.bd=g_glideContext.alpha_blend_rgb_dst;s.bas=g_glideContext.alpha_blend_alpha_src;s.bad=g_glideContext.alpha_blend_alpha_dst; return s;
}
void g98_record_draw(uint32_t caller, bool textured, uint32_t mmid, uint32_t gl) {
    G92Phase* phases[3]={&g_g92PhaseA,&g_g92PhaseB,&g_g92PhaseC};
    for(G92Phase* p:phases) if(p->armed&&!p->done){g98_hist_add(p->families,p->familyCount,caller);if(textured){uint32_t w=0,h=0;auto it=gu_tex_allocations().find(mmid);if(it!=gu_tex_allocations().end()){w=it->second.width;h=it->second.height;}g98_hist_add(p->mmids,p->mmidCount,mmid,gl,w,h);}}
}

uint32_t g99_float_bits(float v) { uint32_t b=0; std::memcpy(&b,&v,sizeof(b)); return b; }
bool g99_vertex_equal(const G99GuestVertex& a,const G99GuestVertex& b) {
    return g99_float_bits(a.x)==g99_float_bits(b.x)&&g99_float_bits(a.y)==g99_float_bits(b.y)&&
           g99_float_bits(a.oow)==g99_float_bits(b.oow)&&g99_float_bits(a.sow)==g99_float_bits(b.sow)&&
           g99_float_bits(a.tow)==g99_float_bits(b.tow);
}
bool g99_host_vertex_equal(const float* a,const float* b) {
    for(int i=0;i<4;++i)if(g99_float_bits(a[i])!=g99_float_bits(b[i]))return false;
    return true;
}
int g99_unique_vertices(const G99FrameData& f) {
    int unique=0;
    for(uint32_t d=0;d<f.capturedDraws;++d)for(int v=0;v<3;++v){
        bool seen=false;
        for(uint32_t pd=0;pd<=d&&!seen;++pd){int vmax=(pd==d?v:3);for(int pv=0;pv<vmax;++pv)if(g99_vertex_equal(f.draws[d].guest[v],f.draws[pd].guest[pv])){seen=true;break;}}
        if(!seen)++unique;
    }
    return unique;
}
struct G99WindowStats { int pairs=0,guestChanged=0,hostChanged=0,bboxChanged=0,mmidChanged=0; double glTiles=0,scanTiles=0; };
G99WindowStats g99_window_stats(const G92Phase& ph,int first,int count) {
    G99WindowStats st;
    for(int n=1;n<count;++n){int i=first+n,p=i-1;if(i>=ph.count)break;const G92Sample&a=ph.samples[p],&b=ph.samples[i];++st.pairs;
        if(a.g99.guestHash!=b.g99.guestHash||a.g99.capturedDraws!=b.g99.capturedDraws)++st.guestChanged;
        if(a.g99.hostHash!=b.g99.hostHash||a.g99.capturedDraws!=b.g99.capturedDraws)++st.hostChanged;
        if(a.g99.mmidSequenceHash!=b.g99.mmidSequenceHash||a.g99.capturedDraws!=b.g99.capturedDraws)++st.mmidChanged;
        if(g99_float_bits(a.g99.minX)!=g99_float_bits(b.g99.minX)||g99_float_bits(a.g99.minY)!=g99_float_bits(b.g99.minY)||g99_float_bits(a.g99.maxX)!=g99_float_bits(b.g99.maxX)||g99_float_bits(a.g99.maxY)!=g99_float_bits(b.g99.maxY))++st.bboxChanged;
        for(int t=0;t<kG82GridTiles;++t){if(a.glTiles[t]!=b.glTiles[t])st.glTiles+=1.0;if(a.scanoutTiles[t]!=b.scanoutTiles[t])st.scanTiles+=1.0;}
    }
    return st;
}
