    IGN_LOG("[G97-GLIDE-UV-SEMANTICS]", "SDK2_sow_tow_are_s_over_w_t_over_w vertex_oow_is_1_over_w OpenGlide_default_STWHINT_0_uses_vertex_oow TMU_oow_consumed_only_with_GR_STWHINT_W_DIFF_TMU0 Ignition_imports_grHints=NO native_G79_rendered_with_stale_tmu_oow=YES");
    IGN_LOG("[G97-HOST-UV-RECONSTRUCTION]", "case=B ordinary_s=sow/vertex_oow ordinary_t=tow/vertex_oow host_u=ordinary_s/texture_width host_v=ordinary_t/texture_height GL_input=size2_normalized_ST VitaGL_FFP_projective_q=NOT_AVAILABLE");
    IGN_LOG("[G97-VITA-NATIVE-UV-COMPARE]", "G96_Vita_raw_sow_tow=finite_sane native_G79_raw_sow_tow=finite_texel_like Vita_vertex_oow=normal native_vertex_oow=normal native_tmu_oow=stale_garbage_but_original_Glide_renders raw_guest_shape_match=YES exact_0x51336_native_capture=PENDING_USER_RUN");
    IGN_LOG("[G97-UV-VERDICT]", "UV_WRAPPER_SEMANTICS_BUG=PROVEN");
    IGN_LOG("[G97-VITA-UV-AFTER-FIX]", "sampled_triangles=%d sampled_vertices=%d raw_nonfinite=%d host_nonfinite=%d raw_huge=%d host_huge=%d host_u_range=%.9g..%.9g host_v_range=%.9g..%.9g", g_g96.count, g_g96.count * 3, rawNonfinite, hostNonfinite, rawHuge, hostHuge, uMin, uMax, vMin, vMax);
    IGN_LOG("[G97-LOGGER-PERF]", "capture=RAM_ONLY_64_TRIANGLES dump=ONCE hot_path_file_writes=NO expected_overhead=G96_0.1_percent_class");
    IGN_LOG("[G97-NEXT-GRAPHICS-TARGET]", "G98=REAL_VITA_VALIDATE_VISUAL_OUTPUT_AND_POST_FIX_UV_METRICS_THEN_IF_STILL_STALE_IDENTIFY_NEXT_DOMINANT_COMPOSITE_FAMILY");
