    IGN_LOG("[G73-NATIVE-BACKEND]", "nglide_version=2.10 file_version=2.61.00.0658 backend=Direct3D9 "
                                    "evidence=strings(Direct3DCreate9,d3d9.dll,\"Failed to load D3D9.DLL library.\") "
                                    "in the SAME untouched pc_oracle glide2x_real.dll used since G66");
