void glide2x_g156_install_hooks(Bridge& br) { g156_install_hooks(br); }   // G156: called by boot_run after the G150 hooks
void glide2x_g156_session_final() { g156_log_summary(true); }   // G156: the cull totals of the session
#else   // G159: the stable DDraw build has no keyboard dialog; the pad sample goes through unchanged
extern "C" void ign_g159_pad_filter(uint32_t*, uint8_t*, uint8_t*, uint8_t*, uint8_t*) {}
